import { Book } from "@/lib/types";

export const proverbs: Book = {
  id: "proverbs",
  name: "Sprüche",
  shortName: "Spr",
  testament: "old",
  introduction: `Das Buch der Sprichwörter\nDas Buch der Sprichwörter ist Gottes Schatzbuch der Weisheit. Es zeigt, wie das Wort Gottes auf jeden Lebensbereich angewendet werden soll: Die wahre Lebensweisheit ruht auf dem Fundament der Gottesfurcht.\nDer größte Teil der Sprüche stammt von Salomo. Wahrscheinlich stellte er auch die \"Sprüche der Weisen\" (22,17-24,34) zusammen und fügte sie seiner Sammlung hinzu. Zur Zeit Hiskias (250 Jahre nach Salomo) lagen die Kapitel 1-24 offensichtlich schon vor. Die Sprüche Agurs und Lemuels (30-31) stammen offenbar von Nichtisraeliten. Schließlich ließ Hiskia von seinen Männern noch einige Sprüche Salomos einfügen (25-29). Die abschließende Anordnung und Zusammenstellung des Buches wird um 700 v.Chr. geschehen sein.\n****Gottes Schatzbuch der Weisheit zeigt, dass Gottes Wort praktisch auf jeden Lebensbereich im Alltag angewendet werden kann.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Sprichwörter von Salomo Ben-David, / dem König von Israel.", heading: "1-9: Gelebte Weisheit\nEinleitung" },
      { number: 2, text: "Sie lehren Weisheit und Selbstbeherrschung, / um guten Rat zu verstehen" },
      { number: 3, text: "und Bildung zu erlangen, / einen Sinn für Recht und Aufrichtigkeit, / und zu leben, wie es Gott gefällt," },
      { number: 4, text: "Unerfahrenen geben sie Klugheit, / jungen Menschen Wissen und Vernunft." },
      { number: 5, text: "Der Kluge hört zu und mehrt seine Kenntnis, / der Erfahrene lernt Führungskunst," },
      { number: 6, text: "versteht Bildrede und Spruch, / Rätsel der Weisen und ihr Wort." },
      { number: 7, text: "Der Anfang der Erkenntnis ist Ehrfurcht vor Jahwe. / Nur Dumme verachten Weisheit und Zucht." },
      { number: 8, text: "Höre, mein Sohn, auf die Mahnung des Vaters, / verwirf die Weisung deiner Mutter nicht!", heading: "Warnung vor Verführung (Lektion 1)" },
      { number: 9, text: "Denn sie sind wie ein Schmuck für den Kopf, / wie eine schöne Kette für den Hals." },
      { number: 10, text: "Mein Sohn, wenn Sünder dich beschwatzen, / dann geh nicht darauf ein!" },
      { number: 11, text: "Wenn sie sagen: \"Komm mit uns! / Wir liegen im Hinterhalt und lauern auf Blut, / wir stellen den Ahnungslosen nach, einfach so!" },
      { number: 12, text: "Wir verschlingen sie wie der Tod; / wir reißen sie aus dem Leben, / befördern sie ins Grab!" },
      { number: 13, text: "Ihr Hab und Gut gehört dann uns, / und wir füllen unsere Häuser damit." },
      { number: 14, text: "Komm, schließ dich uns an, / wir teilen die Beute gerecht!\"" },
      { number: 15, text: "Geh da nicht mit, mein Sohn! / Gib dich nicht mit solchen ab!" },
      { number: 16, text: "Denn sie haben nur Böses im Sinn / und sind schnell zu einer Bluttat bereit." },
      { number: 17, text: "In den Augen aller Vögel / ist das Fangnetz ohne Absicht bestreut*.", footnotes: ["bestreut. D.h. mit Köder."] },
      { number: 18, text: "Doch jene lauern auf ihr eigenes Blut, / sie stellen dem eigenen Leben nach." },
      { number: 19, text: "Und so geht es jedem, der unehrlich reich werden will, / sein Raub raubt dem Räuber das Leben." },
      { number: 20, text: "Die Weisheit ruft auf der Straße, / auf den Plätzen erschallt ihre Stimme." },
      { number: 21, text: "Man hört sie im lärmenden Gewühl / und auch an den Toren der Stadt:" },
      { number: 22, text: "\"Wie lange noch, ihr Dummköpfe, liebt ihr die Dummheit, / wie lange gefällt den Spöttern ihr Spott / und verachten die Narren Erkenntnis?" },
      { number: 23, text: "Nehmt doch endlich meine Mahnung an! / Dann lass ich sprudeln meinen Geist / und öffne den Schatz meines Wissens." },
      { number: 24, text: "Immer wieder rief ich euch an, / doch ihr habt gar nicht zugehört, / habt die ausgestreckte Hand missachtet," },
      { number: 25, text: "wolltet die Mahnung nicht hören / und schlugt jeden Rat in den Wind." },
      { number: 26, text: "Doch wenn das Unglück kommt, werde ich lachen. / Dann spotte ich über euch," },
      { number: 27, text: "wenn das, was ihr fürchtet, wie ein Sturm über euch kommt, / wenn ihr bedrängt seid von Angst und Schrecken." },
      { number: 28, text: "Dann schreit ihr nach mir, doch ich antworte nicht, / dann sucht ihr mich, doch ihr findet mich nicht." },
      { number: 29, text: "Weil sie jede Einsicht hassten / und es ablehnten, Jahwe zu fürchten," },
      { number: 30, text: "weil sie meinen Rat nicht wollten / und meine Mahnung verschmähten," },
      { number: 31, text: "darum sollen sie essen, was sie sich eingebrockt haben, / sollen satt werden am eigenen Rat." },
      { number: 32, text: "Denn Sturheit bringt die Beschränkten um, / die Dummen vernichtet ihre Sorglosigkeit." },
      { number: 33, text: "Doch wer auf mich hört, hat nichts zu befürchten, / kann ohne Angst vor Unglück sein.\"" },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Mein Sohn, wenn du meine Worte annimmst / und meine Gebote bei dir verwahrst,", heading: "Die Suche nach Weisheit (Lektion 2)" },
      { number: 2, text: "wenn du der Weisheit dein Ohr leihst / und dem Verstehen zugeneigt bist," },
      { number: 3, text: "ja, wenn du um Verstand betest / und um Einsicht flehst," },
      { number: 4, text: "wenn du sie suchst wie Silber, / ihnen nachspürst wie einem wertvollen Schatz," },
      { number: 5, text: "dann wirst du die Ehrfurcht begreifen, / die man vor Jahwe haben muss, / und wirst anfangen, Gott zu erkennen." },
      { number: 6, text: "Denn Jahwe gibt Weisheit, / von ihm kommen Erkenntnis und Verstand." },
      { number: 7, text: "Den Aufrichtigen hält er Hilfe bereit, / und für die Redlichen ist er ein Schild." },
      { number: 8, text: "Um die Wege des Rechts zu bewahren, / beschützt er die, die ihm treu sind." },
      { number: 9, text: "Dann wirst du verstehen, was Recht und Gerechtigkeit ist, / Aufrichtigkeit und ein guter Weg." },
      { number: 10, text: "Denn Weisheit wird in dein Herz einziehen / und Erkenntnis beglückt deine Seele." },
      { number: 11, text: "Besonnenheit wacht über dir / und Verständigkeit behütet dich." },
      { number: 12, text: "Das wird dich retten vom Weg des Bösen, / von denen, die die Wahrheit verdrehen," },
      { number: 13, text: "die den geraden Weg verlassen / und auf finsteren Abwegen sind;" },
      { number: 14, text: "von denen, die sich freuen, Böses zu tun, / die jubeln über böse Verkehrtheit," },
      { number: 15, text: "die krumme Wege gehen / und deren Pfad nur in die Irre führt." },
      { number: 16, text: "Das wird dich retten vor der fremden Frau, / der Verführerin, die dir schmeichelt," },
      { number: 17, text: "die den Vertrauten ihrer Jugend verlässt / und den Bund ihres Gottes vergisst." },
      { number: 18, text: "Ihr Haus sinkt hinab in die Totenwelt, / und ihr Weg führt sie zu den Schatten." },
      { number: 19, text: "Wer zu ihr geht, kehrt nie mehr zurück, / er findet den Weg zum Leben nicht wieder." },
      { number: 20, text: "Darum geh du auf dem Weg der Guten / und führe ein Leben, das Gott gefällt." },
      { number: 21, text: "Denn die Gerechten bewohnen das Land, / und die Aufrichtigen bleiben darin." },
      { number: 22, text: "Aber die Gottlosen werden beseitigt, / die Treulosen jätet man aus." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Mein Sohn, vergiss meine Weisung nicht, / behalte meine Vorschriften im Herzen!", heading: "Vertrauen und Gehorsam (Lektion 3)" },
      { number: 2, text: "Sie geben dir ein langes Leben / und sichern dir Jahre im Frieden." },
      { number: 3, text: "Nie sollen dich Liebe und Treue verlassen, / binde sie um deinen Hals und schließe sie in dein Herz!" },
      { number: 4, text: "So findest du Gunst und Anerkennung / bei Gott und den Menschen." },
      { number: 5, text: "Vertraue Jahwe mit ganzem Herzen / und stütze dich nicht auf deinen Verstand!" },
      { number: 6, text: "Such ihn zu erkennen bei dem, was du tust, / dann räumt er dir die Hürden aus dem Weg!" },
      { number: 7, text: "Halte dich nicht selbst für klug, / sondern fürchte Jahwe und meide das Böse!" },
      { number: 8, text: "Das ist Heilung und Wohltat für dich." },
      { number: 9, text: "Ehre Jahwe mit deinem Besitz, / mit dem Besten von dem, was du erntest." },
      { number: 10, text: "Dann füllen sich deine Scheunen mit Korn / und deine Fässer mit jungem Wein." },
      { number: 11, text: "Mein Sohn, verachte nicht die Belehrung Jahwes, / sei nicht unwillig, wenn er dich ermahnt.", heading: "Der Nutzen der Weisheit (Lektion 4)" },
      { number: 12, text: "Denn wen Jahwe liebt, den erzieht er streng, / wie der Vater den Sohn, den er gern hat.*", footnotes: ["Wird im Neuen Testament vom Hebräerbrief nach der LXX zitiert: Hebräer 12,5-6"] },
      { number: 13, text: "Wie glücklich ist der, der Weisheit fand, / der Mann, der Verständnis erwarb." },
      { number: 14, text: "Denn Weisheit besitzen ist besser als Geld / und besser, als Gold zu gewinnen." },
      { number: 15, text: "Sie ist viel kostbarer als Perlen, / dein ganzer Schmuck kommt ihr nicht gleich." },
      { number: 16, text: "In der rechten Hand bietet sie langes Leben / und in ihrer linken Reichtum und Ehre." },
      { number: 17, text: "Ihre Wege sind Wege der Freude / und ihre Pfade führen zum Glück." },
      { number: 18, text: "Sie ist ein Lebensbaum für den, der sie ergreift, / wer an ihr festhält, ist glücklich zu preisen." },
      { number: 19, text: "Durch Weisheit hat Jahwe die Erde gegründet, / durch Verstand den Himmel hingestellt." },
      { number: 20, text: "Sein Wissen brachte die Meere hervor / ließ Regen aus den Wolken fallen." },
      { number: 21, text: "Mein Sohn, verliere es nicht aus den Augen, / bewahre Umsicht und Besonnenheit!", heading: "Die Weisheit im täglichen Leben (Lektion 5)" },
      { number: 22, text: "Sie sind das Leben für dich / und ein schöner Schmuck für deinen Hals." },
      { number: 23, text: "Dann gehst du sicher deinen Weg, / dein Fuß stößt nirgends an." },
      { number: 24, text: "Wenn du dich hinlegst, schreckst du nicht auf, / legst du dich nieder, erfrischt dich dein Schlaf." },
      { number: 25, text: "Du fürchtest dich nicht vor plötzlichem Schrecken, / dem Grauen, das über Gottlose kommt." },
      { number: 26, text: "Denn Jahwe steht dir bei, / er bewahrt deinen Fuß vor der Falle." },
      { number: 27, text: "Versage keine Wohltat dem, der sie braucht. / Wenn du helfen kannst, dann tue es auch!" },
      { number: 28, text: "Sag nicht zu deinem Nächsten: \"Komm später wieder, / morgen gebe ich es dir!\", wo du jetzt schon helfen kannst." },
      { number: 29, text: "Plane nichts Böses gegen deinen Nächsten, / der vertrauensvoll neben dir wohnt!" },
      { number: 30, text: "Geh mit keinem grundlos vor Gericht, / wenn er dir nichts Böses tat." },
      { number: 31, text: "Beneide Gewalttätige nicht, / wähle keinen ihrer Wege!" },
      { number: 32, text: "Denn Jahwe verabscheut den, der auf Abwegen geht. / Doch dem Aufrechten schenkt er Vertrauen." },
      { number: 33, text: "Auf dem Haus des Gottlosen liegt der Fluch Jahwes, / doch die Wohnung des Gerechten* segnet er.", footnotes: ["Der Gerechte im Alten Testament ist ein Mensch, der mit Gott und Menschen im richtigen Verhältnis lebt und sich nach Gottes Geboten richtet. Er steht im Gegensatz zu dem, der sich an Gott und Menschen schuldig macht, dem Gottlosen in Gottes Volk."] },
      { number: 34, text: "Ja, mit Spöttern treibt er Spott, / aber den Demütigen erweist er Gnade.*", footnotes: ["Wird im Neuen Testament von Petrus und Jakobus nach der LXX zitiert: Jakobus 4,6; 1. Petrus 5,5."] },
      { number: 35, text: "Weise kommen zu Ehren, / Dummköpfe tragen Schande davon." },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Hört, ihr Söhne, auf die Mahnung des Vaters, / merkt auf, damit ihr Einsicht lernt,", heading: "Weisheit – der beste Erwerb (Lektion 6)" },
      { number: 2, text: "denn gute Lehre gebe ich euch! / Schiebt meine Weisung nicht weg!" },
      { number: 3, text: "Als ich ein kleiner Junge war, / zart und einzig vor meiner Mutter, / da hat mein Vater mich schon unterwiesen." },
      { number: 4, text: "Er sagte: Präg dir meine Worte ein! / Bewahre meine Gebote und lebe danach!" },
      { number: 5, text: "Erwirb dir Weisheit und Verstand! / Vergiss sie nicht und richte dich nach dem, was ich sage!" },
      { number: 6, text: "Verlass die Weisheit nicht, sie wird dich behüten! / Liebe sie, so beschützt sie dich." },
      { number: 7, text: "Weisheit fängt mit Weisheit an. Erwirb sie dir! / Erwirb Verstand mit allem, was du hast!" },
      { number: 8, text: "Schmiege dich an sie, dann wird sie dich erhöhen, / umarme sie, dann bringt sie dich zu Ehren!" },
      { number: 9, text: "Sie setzt einen schönen Kranz auf deinen Kopf, / eine prächtige Krone schenkt sie dir." },
      { number: 10, text: "Höre, mein Sohn, nimm an, was ich sage, / dann mehren sich dir die Jahre des Lebens.", heading: "Weisheit – der sicherste Weg (Lektion 7)" },
      { number: 11, text: "Im Weg der Weisheit unterweise ich dich, / ich leite dich auf ebener Bahn." },
      { number: 12, text: "Wenn du gehst, wird dein Schritt nicht gehemmt, / wenn du läufst, dann stolperst du nicht." },
      { number: 13, text: "Halte an deiner Erziehung fest, verleugne sie nicht, / bewahre sie, denn sie ist dein Leben!" },
      { number: 14, text: "Komm nicht auf die Bahn der Gesetzlosigkeit, / den Weg der Bösen betrete nie!" },
      { number: 15, text: "Vermeide ihn, betritt ihn nicht, / wende dich von ihm ab und gehe vorbei!" },
      { number: 16, text: "Denn sie schlafen nicht, wenn sie nichts Böses getan, / es raubt ihnen den Schlaf, wenn sie keinen zu Fall gebracht haben." },
      { number: 17, text: "Unrecht ist ihr tägliches Brot, / Gewalt der Wein, den sie trinken." },
      { number: 18, text: "Doch der Pfad der Gerechten ist wie das Morgenlicht, / es strahlt immer heller bis zum vollen Tag." },
      { number: 19, text: "Der Weg der Gottlosen ist wie das Dunkel, / sie wissen nicht, worüber sie gestolpert sind." },
      { number: 20, text: "Mein Sohn, achte auf meine Worte / und hör mir gut zu!", heading: "Weisheit – Hilfe zum Leben (Lektion 8)" },
      { number: 21, text: "Lass sie nicht aus den Augen, / bewahre sie in Herz und Sinn!" },
      { number: 22, text: "Denn sie sind Leben für die, die sie finden, / und Gesundheit für den ganzen Leib." },
      { number: 23, text: "Mehr als alles hüte dein Herz, / denn aus ihm strömt das Leben." },
      { number: 24, text: "Entferne Unwahrheit aus deinem Mund, / die Falschheit von deinen Lippen!" },
      { number: 25, text: "Deine Augen sollen geradeaus schauen, / dein Blick gehe nach vorn." },
      { number: 26, text: "Ebne die Bahn für deinen Fuß, / damit du feste Wege hast." },
      { number: 27, text: "Biege nicht ab, weder rechts noch links, / halte deinen Fuß vom Bösen fern!" },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Mein Sohn, höre meiner Weisheit willig zu / und nimm meine Einsicht zur Kenntnis,", heading: "Warnung vor der Verführerin (Lektion 9)" },
      { number: 2, text: "beachte diese Gedanken, / dass deine Rede das Wissen bewahrt." },
      { number: 3, text: "Denn mit honigsüßen Worten lockt sie dich, die fremde Frau, / ihr Gaumen ist glatter als Öl," },
      { number: 4, text: "doch zuletzt ist sie bitter wie Wermut*, / scharf wie ein zweischneidiges Schwert.", footnotes: ["Wermut. Heilpflanze, deren bittere Aromastoffe auch für Getränke verwendet werden, zum Beispiel in Wermutwein."] },
      { number: 5, text: "Ihre Füße steigen nieder zum Tod, / ihre Schritte streben dem Totenreich zu." },
      { number: 6, text: "Damit du den Weg zum Leben nicht siehst, / lenkt sie dich ab, ohne dass du es merkst." },
      { number: 7, text: "Und nun, ihr Söhne, hört auf mich! / Schlagt meine Warnungen nicht in den Wind!" },
      { number: 8, text: "Geh solch einer Frau aus dem Weg, / komm nicht in die Nähe ihres Hauseingangs!" },
      { number: 9, text: "Sonst überlässt du anderen deine Kraft, / einem Grausamen all deine Jahre." },
      { number: 10, text: "Sonst leben andere von deinem Vermögen, / Fremde besitzen dann, was du erarbeitet hast." },
      { number: 11, text: "Und du stöhnst an deinem Ende, / wenn dein Fleisch und dein Leib sich verzehren" },
      { number: 12, text: "und wenn du jammerst: \"Warum habe ich nur die Erziehung gehasst? / Weshalb habe ich die Mahnung verachtet?" },
      { number: 13, text: "Hätte ich doch aufgepasst / und auf meine Lehrer gehört!" },
      { number: 14, text: "Fast wäre ich vor aller Öffentlichkeit / ins Unglück geraten.\"" },
      { number: 15, text: "Trink Wasser aus deiner eigenen Zisterne, / Wasser, das aus deinem Brunnen quillt." },
      { number: 16, text: "Sollen deine Quellen auf die Straße fließen, / deine Bäche auf die Plätze der Stadt?" },
      { number: 17, text: "Dir allein soll sie gehören, / keinem Fremden neben dir." },
      { number: 18, text: "Deine Quelle sei gesegnet! / Freu dich an der Frau deiner Jugend!" },
      { number: 19, text: "Die liebreizende Gazelle, / das anmutige Reh – ihre Brüste sollen dich immer berauschen, / ihre Liebe bezaubere dich stets!" },
      { number: 20, text: "Warum willst du dich mit einer Fremden vergnügen, / warum die Brüste einer Unbekannten umschlingen?" },
      { number: 21, text: "Denn Jahwe hat die Wege des Menschen im Blick, / auf seine Pfade gibt er acht." },
      { number: 22, text: "Die eigenen Sünden fangen den Gottlosen ein, / die Stricke seiner Sünde fesseln ihn selbst." },
      { number: 23, text: "Er wird sterben aus Mangel an Zucht, / seine große Dummheit bringt ihn ins Grab." },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Mein Sohn, hast du für deinen Nächsten gebürgt, / dich einem Fremden mit Handschlag verpflichtet,", heading: "Vier Gefahren (Lektion 10)" },
      { number: 2, text: "hast du dich durch deine Worte gebunden, / dich gefesselt durch das, was du sagtest?" },
      { number: 3, text: "Dann tue dies, mein Sohn: Reiß dich los! / Denn ein andrer hat dich in seiner Gewalt. / Geh unverzüglich hin und bestürme ihn mit Bitten!" },
      { number: 4, text: "Gönne deinen Augen keinen Schlaf / und deinen Lidern keine Ruhe –" },
      { number: 5, text: "bis du ihm entkommen bist wie die Gazelle dem Jäger, / wie der Vogel dem Zugriff des Fängers." },
      { number: 6, text: "Geh zur Ameise, du Fauler, / sieh, was sie tut und lerne von ihr!" },
      { number: 7, text: "Kein Vorgesetzter treibt sie an," },
      { number: 8, text: "und doch sorgt sie im Sommer für Nahrung, / sammelt ihre Vorräte zur Erntezeit." },
      { number: 9, text: "Wie lange willst du noch liegen, du Fauler? / Wann stehst du endlich auf?" },
      { number: 10, text: "Nur noch ein wenig Schlaf, nur noch ein bisschen Schlummer, / nur noch ein wenig liegen, die Hände gefaltet," },
      { number: 11, text: "und schon kommt dir die Armut ins Haus! Wie ein Landstreicher, / ja, wie ein Räuber überfällt dich die Not." },
      { number: 12, text: "Ein Schuft, ein Bösewicht ist, / wer Lügen verbreitet," },
      { number: 13, text: "wer mit den Augen zwinkert, / mit den Füßen Zeichen gibt, / mit Fingern Andeutungen macht," },
      { number: 14, text: "wer ein Herz voller Falschheit hat, / mit bösen Plänen darin, / und immer einen Streit anfacht." },
      { number: 15, text: "Darum nimmt er ein schreckliches Ende, / plötzlich wird er zerschmettert / und nichts kann ihn retten." },
      { number: 16, text: "Sechs Dinge sind Jahwe verhasst, / und sieben sind ihm ein Gräuel:" },
      { number: 17, text: "stolze Augen, falsche Zunge / und Hände, die Unschuldige töten," },
      { number: 18, text: "ein Herz, das böse Gedanken durchpflügt, / Füße, die dem Verbrechen nachlaufen," },
      { number: 19, text: "ein falscher Zeuge, der Lügen in die Ohren bläst, / und einer, der Zank zwischen Brüdern entfacht." },
      { number: 20, text: "Bewahre, mein Sohn, das Gebot deines Vaters, / verwirf die Weisung deiner Mutter nicht!", heading: "Warnung vor Ehebruch (Lektion 11)" },
      { number: 21, text: "Nimm sie dir zu Herzen, / binde sie um deinen Hals." },
      { number: 22, text: "Beim Gehen soll es dich leiten, / beim Liegen dich beschützen / und beim Wachwerden dir raten." },
      { number: 23, text: "Denn das Gebot ist wie eine Leuchte, / die Weisung wie ein Licht, / und die ermahnende Erziehung ist ein Weg zum Leben," },
      { number: 24, text: "um dich zu schützen vor der schlechten Frau, / der glatten Zunge der Fremden." },
      { number: 25, text: "Begehre nicht ihre Schönheit / und falle nicht herein, wenn sie dir schöne Augen macht." },
      { number: 26, text: "Denn eine Hure bringt dich nur ums Brot, / doch eines anderen Ehefrau um dein kostbares Leben." },
      { number: 27, text: "Kann man Feuer im Gewandbausch tragen, / ohne dass die Kleidung verbrennt?" },
      { number: 28, text: "Kann man über Kohlenglut laufen / und versengt sich nicht die Füße dabei?" },
      { number: 29, text: "So geht es dem, der zur Frau eines anderen geht. / Wer mit ihr schläft, der bleibt nicht ungestraft." },
      { number: 30, text: "Man verachtet den Dieb nicht, wenn er stiehlt, / um sein Verlangen zu stillen, weil der Hunger ihn treibt." },
      { number: 31, text: "Wird er ertappt, muss er es ersetzen, / siebenfach, mit der ganzen Habe seines Hauses." },
      { number: 32, text: "Doch wer mit der Frau eines anderen Ehebruch treibt, / muss den Verstand verloren haben. / Nur wer sich selbst vernichten will, / lässt sich auf so etwas ein." },
      { number: 33, text: "Schläge und Schande bringt es ihm ein / und unauslöschbare Schmach." },
      { number: 34, text: "Denn Eifersucht weckt die Wut des Ehemanns; / hat er zur Rache Gelegenheit, verschont er dich nicht." },
      { number: 35, text: "Er lässt sich auf keine Entschädigung ein, / bleibt unerbittlich, selbst wenn du ihn mit Geld überhäufst." },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Mein Sohn, bewahre meine Worte / und hüte meine Weisung wie einen Schatz!", heading: "Lass dich nicht verführen! (Lektion 12)" },
      { number: 2, text: "Achte auf meine Gebote, dass du lebst; / hüte sie wie deinen Augapfel." },
      { number: 3, text: "Binde sie um deine Finger, / schreibe sie tief in dein Herz!" },
      { number: 4, text: "Nenn die Weisheit deine Schwester / und lass die Einsicht deine Freundin sein," },
      { number: 5, text: "dass sie dich bewahre vor der Frau eines andern, / vor der Fremden, die dich umschmeichelt." },
      { number: 6, text: "Einmal stand ich am Fenster / und blickte durch die Gitter hinaus." },
      { number: 7, text: "Da sah ich eine Gruppe junger Männer, Unerfahrene, / und dabei einen Burschen ohne Verstand." },
      { number: 8, text: "Er ging über die Straße, bog um die Ecke / und nahm den Weg zu ihrem Haus." },
      { number: 9, text: "Es war schon in der Dämmerung, / beim Einbruch der Nacht, wenn es dunkel wird." },
      { number: 10, text: "Schau, da kommt eine Frau ihm entgegen, / wie eine Hure geputzt, / ihre Absicht versteckt." },
      { number: 11, text: "Leidenschaftlich ist sie und hemmungslos; / es hält sie nicht in ihrem Haus." },
      { number: 12, text: "Bald ist sie draußen, bald auf den Plätzen, / an allen Straßenecken lauert sie." },
      { number: 13, text: "Da greift sie ihn und küsst ihn ab / und spricht ihn herausfordernd an:" },
      { number: 14, text: "\"Ich musste heute ein Freudenopfer* bringen, / nun habe ich mein Versprechen erfüllt.", footnotes: ["Beim Freudenopfer wurde im Gegensatz zum Brandopfer nur das Fett auf dem Altar verbrannt. Der größte Teil des Tieres durfte bei einer fröhlichen Opfermahlzeit gemeinsam mit Verwandten und Freunden verzehrt werden."] },
      { number: 15, text: "Darum kam ich heraus, dir zu begegnen, / ich hab dich gesucht und gefunden." },
      { number: 16, text: "Ich habe mein Bett mit Tüchern bezogen, / mit bunten ägyptischen Leinen," },
      { number: 17, text: "und ich habe es mit Myrrhe besprengt, / mit Aloë und Zimt." },
      { number: 18, text: "Komm, wir lieben uns die ganze Nacht, / wir berauschen uns an Liebeslust!" },
      { number: 19, text: "Denn mein Mann ist nicht zu Hause, / er ist auf Reisen, sehr weit fort." },
      { number: 20, text: "Den Geldbeutel hat er mit sich genommen. / Zum Vollmondstag erst kommt er nach Haus.\"" },
      { number: 21, text: "Mit solchen Worten verleitet sie ihn, / verführt ihn mit schmeichelnden Lippen." },
      { number: 22, text: "Er folgt ihr sofort, / wie ein Ochse, den man zum Schlachten führt, / wie ein Hirsch, den das Fangseil umschlingt," },
      { number: 23, text: "bis ein Pfeil seine Leber zerreißt / und er wie ein Vogel im Fangnetz hängt. / Er weiß nicht, dass es um sein Leben geht." },
      { number: 24, text: "Hört mir zu, ihr jungen Männer! / Merkt euch gut, was ich sage!" },
      { number: 25, text: "Lasst euch von solch einer Frau nicht verführen, / irrt nicht auf ihren Wegen umher!" },
      { number: 26, text: "Denn sie hat schon viele gefällt und erschlagen, / die Zahl ihrer Todesopfer ist hoch!" },
      { number: 27, text: "Ihr Haus ist ein Weg zum Scheol* hinab, / er führt in die Kammern des Todes.", footnotes: ["Scheol. Der hebräische Begriff meint den Ort der Toten."] },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Hört doch, wie die Weisheit ruft, / wie die Einsicht ihre Stimme erhebt!", heading: "Ruf der Weisheit (Lektion 13)" },
      { number: 2, text: "Sie steht an den Straßen, dass jeder sie sieht, / sie hat sich an die Kreuzungen gestellt," },
      { number: 3, text: "sie hält sich an den Stadttoren auf / und ruft an den Eingängen laut:" },
      { number: 4, text: "\"Euch, ihr Leute, lade ich ein! / An alle Menschen wende ich mich." },
      { number: 5, text: "Ihr Anfänger, lernt, was Klugheit ist! / Ihr Tagträumer, werdet endlich wach!" },
      { number: 6, text: "Hört zu, ich gebe euch einen wertvollen Rat! / Die Wahrheitsliebe öffnet mir den Mund." },
      { number: 7, text: "Was ich sage, ist nichts als die Wahrheit, / denn ich verabscheue Gesetzlosigkeit." },
      { number: 8, text: "Alle meine Worte sind recht, / keins davon ist hinterlistig und falsch." },
      { number: 9, text: "Dem Einsichtigen sind sie alle recht / und dem, der sie verstehen will, klar." },
      { number: 10, text: "Sucht meine Unterweisung und nicht Silberschmuck! / Nehmt Erkenntnis lieber an als reines Gold!" },
      { number: 11, text: "Weisheit ist besser als kostbare Perlen, / alle Juwelen ersetzen sie nicht.\"" },
      { number: 12, text: "Ich, die Weisheit, bin mit der Klugheit im Bund. / Durch Umsicht finde ich Erkenntnis und Rat." },
      { number: 13, text: "Jahwe zu ehren heißt Böses zu hassen. / Ja, ich hasse Hochmut und Stolz / und unrechtes Tun / und einen Mund, der die Worte verdreht." },
      { number: 14, text: "Bei mir ist Hilfe und Rat. / Ich habe Einsicht und habe auch Macht." },
      { number: 15, text: "Könige regieren durch mich / und Herrscher entscheiden gerecht." },
      { number: 16, text: "Durch mich versehen die Oberen ihr Amt, / die Vornehmen und die Verwalter des Rechts." },
      { number: 17, text: "Ich liebe, die mich lieben; / und die mich suchen, finden mich." },
      { number: 18, text: "Ich biete Reichtum und Ehre, / bleibendes Gut und gerechten Lohn." },
      { number: 19, text: "Was ihr von mir bekommt, ist besser als das reinste Gold / und wertvoller als erlesenes Silber." },
      { number: 20, text: "Ich gehe den Weg der Gerechtigkeit / und zwar mitten auf der Straße des Rechts." },
      { number: 21, text: "Denen, die mich lieben, gebe ich, was bleibt, / und ihre Häuser fülle ich." },
      { number: 22, text: "Bevor alles anfing, besaß mich Jahwe, / vor seinen Werken, vor aller Zeit." },
      { number: 23, text: "Schon ewig war ich eingesetzt, von Anfang an, / noch vor Beginn der Welt." },
      { number: 24, text: "Als noch keine Meere waren, wurde ich geboren, / als es noch keine wasserreichen Quellen gab." },
      { number: 25, text: "Noch vor den Hügeln wurde ich geboren; / die Berge waren noch nicht eingesenkt," },
      { number: 26, text: "die Erde hatte er noch nicht gemacht, / das feste Land und seine Felder." },
      { number: 27, text: "Als er den Himmel wölbte, war ich dabei, / als er den Kreis des Horizonts abmaß über dem Meer," },
      { number: 28, text: "als er die Wolken hoch oben zusammenzog / und die Quellen aus der Tiefe sprudeln ließ;" },
      { number: 29, text: "als er das Meer in seine Schranken wies, / die es nicht überschreiten darf, / als er die Fundamente der Erde abmaß," },
      { number: 30, text: "da war ich als geliebtes Kind bei ihm. / Ich war seine Freude Tag für Tag / und spielte vor ihm allezeit." },
      { number: 31, text: "Ich spielte auf dem Rund seiner Erde, / und es war meine Freude, bei den Menschen zu sein." },
      { number: 32, text: "Nun denn, ihr jungen Leute, hört auf mich! / Wie glücklich sind alle, die auf meinen Wegen gehen!" },
      { number: 33, text: "Hört auf die Mahnung, und schlagt sie nicht in den Wind! / Hört darauf und werdet klug!" },
      { number: 34, text: "Wie glücklich ist der, der auf mich hört, / der Tag und Nacht vor meinen Türen steht, / der in meinem Torweg wacht." },
      { number: 35, text: "Denn wer mich findet, hat Leben gefunden / und das Wohlgefallen Jahwes." },
      { number: 36, text: "Doch wer mich verfehlt, schadet sich selbst. / Alle, die mich hassen, lieben den Tod." },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Die Weisheit hat ihr Haus gebaut, / hat es mit sieben Säulen ausgeschmückt.", heading: "Frau Weisheit und Frau Torheit laden zu Gast (Zusammenfassung)" },
      { number: 2, text: "Sie hat ihr Vieh geschlachtet, ihren Wein gemischt / und auch schon ihren Tisch gedeckt." },
      { number: 3, text: "Nun schickt sie ihre Dienstmädchen / auf den Marktplatz der Stadt:" },
      { number: 4, text: "\"Wer unerfahren ist, der kehre hier ein! / Wer etwas lernen will, ist eingeladen!\" / So rufen sie aus." },
      { number: 5, text: "\"Kommt und esst von meinem Brot / und trinkt von meinem guten Wein!" },
      { number: 6, text: "Lasst ab von eurer Dummheit, wählt doch das Leben, / und geht auf dem Weg des Verstands!\"" },
      { number: 7, text: "Wer einen Spötter ermahnt, erntet nur Schimpf; / und wer einen Gesetzlosen rügt, kriegt sein Teil davon ab." },
      { number: 8, text: "Ermahne einen Spötter nicht, sonst hasst er dich nur! / Ermahne den Weisen, er liebt dich dafür!" },
      { number: 9, text: "Unterrichte den Weisen, dann wird er noch weiser; / belehre den Gerechten, so lernt er noch mehr!" },
      { number: 10, text: "Der Anfang aller Weisheit ist Ehrfurcht vor Jahwe. / Den Heiligen erkennen, das ist Verstand." },
      { number: 11, text: "Denn durch mich werden deine Jahre vermehrt, / durch mich verlängert sich dein Leben." },
      { number: 12, text: "Wenn du weise bist, dann hast du selbst etwas davon. / Und wenn du ein Spötter bist, musst du die Folgen selbst tragen." },
      { number: 13, text: "Frau Torheit ist eine schamlose Frau / und hat nie etwas erkannt!" },
      { number: 14, text: "Da sitzt sie an ihrem Hauseingang, / sie thront auf dem Marktplatz der Stadt," },
      { number: 15, text: "um einzuladen, den, der vorübergeht, / der einen geraden Weg verfolgt:" },
      { number: 16, text: "\"Wer unerfahren ist, der kehre hier ein! / Wer etwas lernen will, ist eingeladen!" },
      { number: 17, text: "Gestohlenes Wasser ist süß, / und heimlich entwendetes Brot, / das schmeckt besonders gut!\"" },
      { number: 18, text: "Doch wer ihr folgt, weiß nicht, dass dort die Schatten hausen, / denn die Geister der Toten sind bei ihr zu Gast." },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Es folgen Sprichwörter Salomos.Ein kluger Sohn ist Vaters Glück, / doch ein dummer ist Mutters Kummer.", heading: "10-24: Gelehrte Weisheit\nSprichwörter Salomos" },
      { number: 2, text: "Unrecht Gut gedeiht nicht gut, / doch Gerechtigkeit rettet vom Tod." },
      { number: 3, text: "Jahwe lässt keinen verhungern, der gottgefällig lebt, / doch die Gier der Gottlosen stößt er zurück." },
      { number: 4, text: "Wer lässig schafft, wird arm, / doch fleißige Hände machen reich." },
      { number: 5, text: "Wer im Sommer sammelt, ist ein kluger Sohn, / doch wer die Ernte verschläft, hat Verachtung verdient." },
      { number: 6, text: "Das Haupt des Gerechten ist mit Segen gekrönt, / doch im Mund des Gottlosen versteckt sich Gewalt." },
      { number: 7, text: "Das Andenken des Gerechten ist Segen, / doch der Name des Gottlosen verwest." },
      { number: 8, text: "Ein weiser Mensch nimmt Weisungen an, / doch wer Unsinn redet, kommt zu Fall." },
      { number: 9, text: "Wer ehrlich ist, tritt sicher auf, / doch wer krumme Wege geht, fängt zu schwitzen an." },
      { number: 10, text: "Wer böswillig zwinkert, verursacht nur Leid, / und wer Unsinn redet, kommt zu Fall." },
      { number: 11, text: "Der Mund des Gerechten ist eine Quelle des Lebens, / doch im Mund eines Gottlosen versteckt sich Gewalt." },
      { number: 12, text: "Hass verlangt nach Streit, / doch Liebe deckt alle Vergehen zu." },
      { number: 13, text: "Auf den Lippen des Verständigen findet man Weisheit, / auf dem Rücken des Unverständigen einen Stock." },
      { number: 14, text: "Weise sparen ihr Wissen auf, / Narren reden schnell Unheil herbei." },
      { number: 15, text: "Für den Reichen ist der Besitz eine sichere Burg, / für den Armen führt Armut zum Untergang." },
      { number: 16, text: "Der Verdienst des Gerechten erhält ihn am Leben, / der Gottlose gibt das Geld zum Sündigen aus." },
      { number: 17, text: "Wer auf Mahnungen hört, ist auf dem Weg zum Leben, / wer sie verachtet, ist auf einer falschen Spur." },
      { number: 18, text: "Wer den Hass versteckt, muss lügen, / doch wer Verleumdung ausstreut, ist verrückt." },
      { number: 19, text: "Wo viele Worte sind, geht es ohne Sünde nicht ab, / doch wer die Zunge im Zaum hält, ist klug." },
      { number: 20, text: "Die Worte eines Gerechten, sind wie erlesenes Silber, / doch das Gewissen eines Gesetzlosen ist wenig wert." },
      { number: 21, text: "Das Reden des Gerechten macht viele Menschen satt, / doch ein Dummkopf stirbt durch Unverstand." },
      { number: 22, text: "Wohlstand kommt durch den Segen Jahwes, / eigenes Mühen vergrößert ihn nicht." },
      { number: 23, text: "Nur dem Dummen machen Schandtaten Spaß, / ein Verständiger erfreut sich an Weisheit." },
      { number: 24, text: "Was der Gottlose fürchtet, kommt über ihn, / doch der Gerechte bekommt, was er wünscht." },
      { number: 25, text: "Ist der Sturm vorüber, ist der Gottlose nicht mehr da, / doch der Gerechte steht immer auf festem Grund." },
      { number: 26, text: "Wie Essig für die Zähne und Rauch für die Augen / ist ein Fauler für den, der ihn zur Arbeit schickt." },
      { number: 27, text: "Wer Jahwe ehrt, wird länger leben, / wer ihn missachtet, verkürzt seine Zeit." },
      { number: 28, text: "Der Gerechte kann Freude erwarten, / doch der Gottlose hat seine Hoffnung verspielt." },
      { number: 29, text: "Wer sich an Jahwe hält, hat seine Zuflucht in ihm, / doch wer Unrecht tut, für den ist er der Untergang." },
      { number: 30, text: "Wer lebt, wie es Gott gefällt, hat immer sicheren Grund, / doch wer Gott missachtet, verliert sein Land." },
      { number: 31, text: "Wer lebt, wie es Gott gefällt, lässt Weisheit sprießen, / doch eine falsche Zunge schneidet man ab." },
      { number: 32, text: "Die Worte des Gerechten tun dir wohl, / doch der Mund des Gottlosen verbreitet Verkehrtheit." },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Falsche Waage verabscheut Jahwe, / nur volles Gewicht gefällt ihm gut." },
      { number: 2, text: "Kommt Übermut, dann kommt auch Schande, / doch Weisheit ist mit Demut verknüpft." },
      { number: 3, text: "Aufrichtige werden von Ehrlichkeit geführt; / Treulose zerfrisst ihre Falschheit." },
      { number: 4, text: "Reichtum nützt nichts, wenn Gott zornig ist, / wer Gott gehorcht, rettet sein Leben." },
      { number: 5, text: "Dem Aufrichtigen ebnet sein Gehorsam den Weg, / doch Gesetzlose kommen durch ihre Bosheit zu Fall." },
      { number: 6, text: "Die Aufrichtigen rettet ihre Treue, / die Treulosen fängt die eigene Gier." },
      { number: 7, text: "Wenn der Gottlose stirbt, vergeht seine Hoffnung, / und seine Erwartungen verlieren sich." },
      { number: 8, text: "Der Gerechte wird aus Bedrängnis befreit, / der Gottlose kommt stattdessen hinein." },
      { number: 9, text: "Wer Gott verachtet, verdirbt auch seinen Nächsten, / wer lebt, wie es Gott gefällt, wird durch Erkenntnis befreit." },
      { number: 10, text: "Geht es den Gottesfürchtigen gut, freut sich die Stadt, / kommen die Gottlosen um, jubelt sie auf." },
      { number: 11, text: "Durch den Segen ehrlicher Menschen kommt eine Stadt hoch, / das Gerede Gesetzloser reißt sie herab." },
      { number: 12, text: "Wer über andere lästert, hat keinen Verstand, / doch ein Verständiger hält seinen Mund." },
      { number: 13, text: "Wer als Verleumder umherzieht, gibt Anvertrautes preis, / doch ein Zuverlässiger hält die Sache geheim." },
      { number: 14, text: "Wo es an Führung mangelt, zerfällt ein Volk, / Rettung kommt durch viele Berater." },
      { number: 15, text: "Wer für einen Fremden bürgt, ist übel dran, / doch wer den Handschlag hasst, ist sicher." },
      { number: 16, text: "Durch Liebenswürdigkeit kommt eine Frau zu Ehren, / durch Tatkraft Männer zu Vermögen." },
      { number: 17, text: "Wer zu anderen gütig ist, tut sich selber wohl, / doch ein Grausamer schneidet sich ins eigene Fleisch." },
      { number: 18, text: "Unsicher ist der Gewinn des Gottlosen; / wer lebt, wie es Gott gefällt, erhält sicheren Lohn." },
      { number: 19, text: "So gewiss die Gerechtigkeit zum Leben führt, / so sicher führt die Jagd nach dem Bösen zum Tod." },
      { number: 20, text: "Verschlagene Menschen verabscheut Jahwe, / doch die, die geradlinig leben, gefallen ihm gut." },
      { number: 21, text: "Die Hand darauf: Der Böse bleibt nicht ungestraft! / Aber die Nachkommen des Gerechten bleiben verschont." },
      { number: 22, text: "Wie ein goldener Ring im Rüssel einer Sau / ist eine schöne Frau, die keinen Anstand hat." },
      { number: 23, text: "Wer lebt, wie es Gott gefällt, darf lauter Gutes erwarten; / doch wer Gott missachtet, hofft nur auf Zorn." },
      { number: 24, text: "Mancher teilt mit vollen Händen aus und bekommt doch immer mehr, / ein anderer spart über Gebühr und wird doch arm dabei." },
      { number: 25, text: "Wer andern Gutes tut, dem geht es selber gut, / wer anderen Erfrischung gibt, wird selbst erfrischt." },
      { number: 26, text: "Wer in Notzeiten Getreide zurückhält, wird von den Leuten verflucht, / wer es aber verkauft, den segnen sie." },
      { number: 27, text: "Wer auf das Gute aus ist, findet Gefallen bei Gott; / wer Böses ausheckt, zieht es sich auf den Hals." },
      { number: 28, text: "Wer auf sein Geld vertraut, kommt zu Fall; / doch wer lebt, wie es Gott gefällt, wird sprossen wie das frische Grün." },
      { number: 29, text: "Wer seine Familie zerrüttet, steht am Schluss vor dem Nichts, / und der Dumme wird ein Sklave des Weisen." },
      { number: 30, text: "Der Gerechte ist ein Baum des Lebens; / und der Weise gewinnt Menschen für sich." },
      { number: 31, text: "Wer Gott mit Ehrfurcht begegnet, bekommt den Lohn schon auf Erden, / wer Gott verachtet und in Sünde lebt, erst recht.*", footnotes: ["Wird im Neuen Testament von Petrus nach der LXX zitiert: 1. Petrus 4,18."] },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Wer Zurechtweisung liebt, der liebt es zu lernen, / wer keine Ermahnung erträgt, ist einfach nur dumm." },
      { number: 2, text: "Der Gute gewinnt Gefallen bei Gott, / doch den Intriganten verurteilt Jahwe." },
      { number: 3, text: "Wer Unrecht tut, hat keinen Bestand, / doch der Gerechte steht wie ein tief verwurzelter Baum." },
      { number: 4, text: "Eine fleißige Frau ist eine Krone für ihren Mann, / doch eine Schlampe ist wie Fäulnis im Skelett." },
      { number: 5, text: "Ein Gerechter denkt an das Recht, / ein Gesetzloser plant Betrug." },
      { number: 6, text: "Das Reden von Gottlosen ist wie ein Lauern auf Blut, / doch die Worte Wahrheitsliebender retten davor." },
      { number: 7, text: "Gesetzlose stürzen und sind nicht mehr, / doch das Haus der Gerechten besteht." },
      { number: 8, text: "Jeder wird nach dem Maß seiner Klugheit gelobt, / doch einen Wirrkopf verachtet man." },
      { number: 9, text: "Besser unbeachtet bleiben und einen Diener haben, / als ein Wichtigtuer sein, der nichts zu essen hat." },
      { number: 10, text: "Den Gerechten kümmert das Wohl seines Viehs, / wer Gott verachtet, hat ein grausames Herz." },
      { number: 11, text: "Wer seine Felder bestellt, hat auch genügend Brot, / doch wer Nichtigkeiten nachjagt, ist ohne Verstand." },
      { number: 12, text: "Der Gottlose beneidet Böse um ihren Gewinn, / doch die Wurzel der Gerechten gibt Halt." },
      { number: 13, text: "Der Böse verfängt sich im Lügengespinst, / der Gerechte entgeht der Gefahr." },
      { number: 14, text: "Wer Gutes sagt, lebt auch gut davon, / und was seine Hände reifen lassen, das kehrt zu ihm zurück." },
      { number: 15, text: "Ein Dummkopf hält alles, was er tut, für recht, / doch ein Weiser hört auf Rat." },
      { number: 16, text: "Ein Dummkopf zeigt seinen Ärger sofort, / doch wer die Beleidigung einsteckt, ist klug." },
      { number: 17, text: "Ein wahrhaftiger Zeuge fördert das Recht, / ein falscher unterstützt den Betrug." },
      { number: 18, text: "Wer unbedacht schwätzt, verletzt mit dem Schwert, / doch die Worte von Weisen sind heilende Kräuter." },
      { number: 19, text: "Wahrheit besteht in Ewigkeit, / Lüge vergeht in kürzester Zeit!" },
      { number: 20, text: "Wer Böses plant, schadet sich selbst, / wer zum Frieden rät, der kann sich freuen." },
      { number: 21, text: "Kein Unheil stößt dem Gerechten zu, / doch die Gottlosen werden vom Unglück erdrückt." },
      { number: 22, text: "Ein Mensch, der lügt, ist Jahwe ein Gräuel, / nur wer wahrhaftig ist, gefällt ihm wohl." },
      { number: 23, text: "Ein kluger Mensch hält sein Wissen verborgen, / doch ein Narr schreit seine Dummheit heraus." },
      { number: 24, text: "Fleißige werden die Herrschaft erringen, / Faule müssen Zwangsarbeit tun." },
      { number: 25, text: "Sorgen drücken einen Menschen nieder, / doch ein gutes Wort richtet ihn auf." },
      { number: 26, text: "Der Gerechte zeigt seinem Freund den Weg, / wer Gott verachtet, geht in die Irre." },
      { number: 27, text: "Wer lässig ist, fängt nie ein Wild, / doch der Fleißige schafft bleibenden Besitz." },
      { number: 28, text: "Wer Gott gehorcht, findet das Leben. / Auf diesem Weg gibt es keinen Tod." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Ein verständiger Sohn hört, wenn er zurechtgewiesen wird, / doch der Spötter hört nicht auf die Ermahnung." },
      { number: 2, text: "Vom Ertrag seiner Worte kann ein Mann gut leben, / gemeine Menschen aber lieben die Gewalt." },
      { number: 3, text: "Wer den Mund hält, bewahrt sein Leben, / wer ihn aufreißt, dem droht Verderben." },
      { number: 4, text: "Ein fauler Mensch hat viele Wünsche, erreicht aber nichts, / doch der Fleißige erfüllt sie sich." },
      { number: 5, text: "Wer Gott gehorcht, hasst Lug und Trug, / wer Gott verachtet, bringt Schande und Spott." },
      { number: 6, text: "Gottesfurcht bewahrt die Ehrlichen, / Gesetzlosigkeit bringt die Sünder zu Fall." },
      { number: 7, text: "Mancher stellt sich reich und hat doch nichts; / mancher stellt sich arm und ist steinreich." },
      { number: 8, text: "Ein Reicher kann Lösegeld für sein Leben bezahlen, / doch ein Armer wird gar nicht erst erpresst." },
      { number: 9, text: "Das Licht der Gerechten strahlt hell, / doch die Lampe der Gottlosen erlischt." },
      { number: 10, text: "Übermut bringt nichts als Streit, / doch wer sich beraten lässt, ist klug." },
      { number: 11, text: "Vermögen aus dem Nichts verliert sich bald, / doch wer allmählich sammelt, gewinnt immer mehr." },
      { number: 12, text: "Endloses Hoffen macht das Herz krank, / doch ein erfüllter Wunsch ist wie ein Lebensbaum." },
      { number: 13, text: "Wer das Wort verachtet, muss dafür bezahlen, / doch wer Ehrfurcht hat vor dem Gebot, der wird belohnt." },
      { number: 14, text: "Die Lehre des Weisen ist eine Quelle des Lebens, / die vor den Fallen des Todes bewahrt." },
      { number: 15, text: "Wer gute Einsicht hat, verschafft sich Gunst, / doch der Weg der Verräter ist steinhart." },
      { number: 16, text: "Jeder Kluge handelt mit Bedacht, / ein Narr kramt seine Dummheit aus." },
      { number: 17, text: "Ein gesetzloser Bote richtet Unheil an, / doch ein treuer Gesandter macht es wieder gut." },
      { number: 18, text: "Armut und Schande trifft den, der sich nichts sagen lässt, / doch wer Kritik annimmt, wird geehrt." },
      { number: 19, text: "Es ist schön, wenn Wünsche sich erfüllen, / doch ein Dummkopf lässt dafür nicht vom Bösen ab." },
      { number: 20, text: "Wer mit Weisen umgeht, wird weise, / doch wer sich mit Narren einlässt, schadet sich." },
      { number: 21, text: "Die Sünder werden von Unheil verfolgt; / wer Gott gehorcht, wird mit Glück belohnt." },
      { number: 22, text: "Das Erbe des Guten ist noch für die Enkel, / doch das Vermögen des Sünders ist für Gerechte bestimmt." },
      { number: 23, text: "Viel Nahrung trägt der Acker der Armen, / doch manches wird durch Unrecht weggerafft." },
      { number: 24, text: "Wer seine Rute schont, der hasst seinen Sohn, / doch wer ihn liebt, erzieht ihn beizeiten." },
      { number: 25, text: "Wer gottrecht lebt, hat satt zu essen, / doch der Magen der Gottlosen bleibt leer." },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Die Weisheit baut Familie und Haus, / doch die Torheit reißt alles wieder ein." },
      { number: 2, text: "Wer seinen Weg geradeaus geht, hat Ehrfurcht vor Jahwe, / doch wer krumme Wege einschlägt, verachtet ihn." },
      { number: 3, text: "Das Gerede eines Narren ist eine Rute für seinen Stolz, / doch der Weise überlegt, was er sagt." },
      { number: 4, text: "Wo keine Rinder sind, da bleibt die Krippe leer, / doch die Kraft des Stiers bringt reichen Ertrag." },
      { number: 5, text: "Ein zuverlässiger Zeuge wird nicht lügen, / doch ein falscher lügt, was er kann." },
      { number: 6, text: "Ein Spötter sucht die Weisheit und findet sie nicht, / doch der Vernünftige entdeckt sie schnell." },
      { number: 7, text: "Wenn du einem Dummen gegenübertrittst, / hörst du kein vernünftiges Wort." },
      { number: 8, text: "Die Weisheit lässt den Klugen wissen, was er tut, / doch Narren betrügen sich durch ihre Dummheit selbst." },
      { number: 9, text: "Schuld macht Narren zu Spöttern, / doch ehrliche Menschen gefallen Gott." },
      { number: 10, text: "Das Herz allein kennt seinen tiefen Schmerz, / und auch seine Freude teilt es mit keinem." },
      { number: 11, text: "Gesetzlosen wird das Haus zerstört, / doch das Zelt der Gerechten gedeiht." },
      { number: 12, text: "Mancher wähnt sich auf dem richtigen Weg, / doch am Ende führt er ihn zum Tod." },
      { number: 13, text: "Selbst beim Lachen kann man traurig sein, / und wenn es vorbei ist, bleibt der Schmerz." },
      { number: 14, text: "Wer krumme Wege geht, bekommt, was er verdient, / der gute Mann wird mit Gutem belohnt." },
      { number: 15, text: "Der Gedankenlose glaubt allem Geschwätz, / der Kluge achtet auf jeden Schritt." },
      { number: 16, text: "Der Weise scheut sich und weicht dem Bösen aus, / doch der Narr braust auf und fühlt sich im Recht." },
      { number: 17, text: "Ein hitziger Mann macht manche Dummheit, / doch der Hinterlistige wird immer gehasst." },
      { number: 18, text: "Der Einfältige wird seine Dummheit erben, / doch der Kluge wird mit Erkenntnis gekrönt." },
      { number: 19, text: "Die Bösen müssen sich vor den Guten verneigen / und die Gottlosen an den Türen der Gerechten." },
      { number: 20, text: "Ein Armer ist selbst seinem Nächsten verhasst, / doch Reiche haben viele Freunde." },
      { number: 21, text: "Wer seinen Nächsten verachtet, versündigt sich, / doch glücklich, wer sich über Hilflose erbarmt." },
      { number: 22, text: "Wer Böses plant, wird in die Irre gehen, / doch wer gute Absichten hat, erntet Liebe und Treue." },
      { number: 23, text: "Harte Arbeit führt zum Gewinn, / bloßes Gerede zum Verlust." },
      { number: 24, text: "Reichtum ist die Krone der Verständigen, / der Kranz der Narren ist ihr Unverstand." },
      { number: 25, text: "Ein ehrlicher Zeuge ist ein Lebensretter, / wer Lügen vorbringt, verbreitet Betrug." },
      { number: 26, text: "Wer Jahwe ehrt, lebt in Sicherheit, / auch seine Kinder werden bewahrt." },
      { number: 27, text: "Wer Jahwe ehrt, ist an der Quelle des Lebens / und wird vor tödlichen Fehlern bewahrt." },
      { number: 28, text: "In der Größe seines Volkes liegt die Ehre des Königs, / doch ein Rückgang der Bevölkerung ist sein Untergang." },
      { number: 29, text: "Wer ruhig bleibt, hat viel Verstand, / doch wer aufbraust, zeigt nur seine Unvernunft." },
      { number: 30, text: "Gelassenheit hält auch den Körper gesund, / doch Leidenschaft ist Knochenfraß." },
      { number: 31, text: "Wer Schwache bedrückt, verhöhnt deren Schöpfer, / doch wer Hilflosen hilft, ehrt den, der sie geschaffen hat." },
      { number: 32, text: "In seinem Unglück kommt der Gottlose um, / doch wer mit Gott lebt, ist auch im Tod noch geborgen." },
      { number: 33, text: "Im Herz des Verständigen ist die Weisheit zu Haus, / doch beim Dummkopf fühlt sie sich nicht wohl." },
      { number: 34, text: "Gerechtigkeit macht ein Volk groß, / doch Sünde ist für jedes Volk eine Schande." },
      { number: 35, text: "Ein kluger Diener wird von seinem Herrscher geschätzt, / doch einen Schändlichen trifft sein Zorn." },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Eine sanfte Antwort besänftigt den Zorn, / doch ein kränkendes Wort heizt ihn an." },
      { number: 2, text: "Die Worte von Weisen fördern das Wissen, / der Mund von Narren schwatzt dummes Zeug." },
      { number: 3, text: "Jahwes Augen sind überall / und wachen über Böse und Gute." },
      { number: 4, text: "Ein freundliches Wort ist wie ein Lebensbaum, / eine falsche Zunge bricht den Lebensmut." },
      { number: 5, text: "Ein Dummkopf lehnt jede Erziehung ab, / doch wer sich ermahnen lässt, wird klug." },
      { number: 6, text: "Wer Gott gehorcht, hat mehr als genug, / wer ihn missachtet, kann nicht nutzen, was er gewinnt." },
      { number: 7, text: "Die Lippen der Weisen verbreiten Erkenntnis, / das Herz von Dummen ist falsch." },
      { number: 8, text: "Das Opfer von Gottlosen ist Jahwe ein Gräuel, / das Gebet von Aufrichtigen gefällt ihm gut." },
      { number: 9, text: "Das Treiben der Gottlosen verabscheut Jahwe, / doch liebt er den, der ihm gehorchen will." },
      { number: 10, text: "Wer krumme Wege geht, wird hart bestraft, / wer die Ermahnung hasst, kommt um." },
      { number: 11, text: "Totenreich und Unterwelt sind offen vor Jahwe, / wie viel mehr dann die Herzen der Menschen." },
      { number: 12, text: "Der Spötter mag es nicht, dass man ihn rügt, / und zu den Weisen geht er nicht." },
      { number: 13, text: "Ein fröhliches Herz macht ein strahlendes Gesicht, / bei Herzenskummer ist der Mut gebeugt." },
      { number: 14, text: "Das Herz des Verständigen sucht nach Wissen, / der Mund der Dummen redet dummes Zeug." },
      { number: 15, text: "Wer Kummer hat, hat keinen guten Tag, / doch ein fröhliches Herz ist ein tägliches Fest." },
      { number: 16, text: "Besser wenig in Ehrfurcht vor Jahwe, / als große Schätze und ständige Sorge." },
      { number: 17, text: "Besser nur Grünkost und Liebe dabei, / als der schönste Braten, übergossen mit Hass." },
      { number: 18, text: "Ein Hitzkopf fängt Streit an, / ein Besonnener besänftigt ihn." },
      { number: 19, text: "Der Weg des Faulen ist wie mit Dornen versperrt, / doch der Pfad von Aufrechten ist frei." },
      { number: 20, text: "Ein kluger Sohn erfreut den Vater, / nur ein Dummkopf missachtet die Mutter." },
      { number: 21, text: "Dem Unverständigen macht Dummheit Spaß, / wer Einsicht hat, geht den geraden Weg." },
      { number: 22, text: "Wo es an Beratung fehlt, da scheitern die Pläne, / wo viele Ratgeber sind, da gibt es Erfolg." },
      { number: 23, text: "Jeden freut es, wenn er Antwort geben kann; / wie gut ist ein Wort zur richtigen Zeit!" },
      { number: 24, text: "Wer Einsicht hat, geht den Weg aufwärts zum Leben, / damit er der Totenwelt unten entgeht." },
      { number: 25, text: "Das Haus der Stolzen reißt Jahwe ein, / doch den Grenzstein der Witwe stellt er wieder auf." },
      { number: 26, text: "Böse Pläne sind Jahwe ein Gräuel, / doch freundliche Worte erfreuen ihn." },
      { number: 27, text: "Unehrlicher Gewinn bringt die Familie in Not, / doch wer Bestechung hasst, wird leben." },
      { number: 28, text: "Der Gerechte überlegt sich, was er sagt, / doch ein gottloser Mund schäumt Böses aus." },
      { number: 29, text: "Jahwe ist den Gottlosen fern, / doch das Beten der Gerechten hört er." },
      { number: 30, text: "Leuchtende Augen erfreuen das Herz, / die gute Nachricht gibt neue Kraft." },
      { number: 31, text: "Wer auf heilsame Zurechtweisung hört, / hält sich bei den Weisen auf." },
      { number: 32, text: "Wer Ordnungen verwirft, verachtet sich selbst, / wer auf Mahnungen hört, erwirbt Verstand." },
      { number: 33, text: "Ehrfurcht vor Jahwe ist Erziehung zur Weisheit; / und Demut geht der Ehre voraus." },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Der Mensch stellt seine Überlegungen an, / doch was er sagt, kommt von Jahwe.", heading: "(Sprichwörter Salomos)" },
      { number: 2, text: "Der Mensch hält alles, was er tut, für recht, / doch Jahwe prüft die Motive." },
      { number: 3, text: "Vertraue Jahwe deine Vorhaben an, / dann werden deine Pläne gelingen." },
      { number: 4, text: "Alles schuf Jahwe zu seinem Zweck, / auch den Gottlosen – für den Unheilstag." },
      { number: 5, text: "Stolze Menschen verabscheut Jahwe. / Die Hand darauf! Sie entgehen ihrer Strafe nicht." },
      { number: 6, text: "Durch Liebe und Treue wird Schuld gesühnt, / durch Ehrfurcht vor Jahwe bleibt man dem Bösen fern." },
      { number: 7, text: "Wenn das Tun eines Menschen Jahwe gefällt, / macht er auch dessen Feinde zum Frieden bereit." },
      { number: 8, text: "Besser wenig mit Gerechtigkeit, / als großen, aber unrechten Gewinn." },
      { number: 9, text: "Das Herz des Menschen plant seinen Weg, / aber Jahwe lenkt seinen Schritt." },
      { number: 10, text: "Ein Gottesurteil ist auf den Lippen des Königs, / beim Rechtsspruch irrt er sich nicht." },
      { number: 11, text: "Es ist Jahwes Wille, dass die Waage einwandfrei ist / und die Gewichte im Beutel stimmen." },
      { number: 12, text: "Gottlose Taten verabscheut der König, / denn sein Thron steht nur durch Gerechtigkeit fest." },
      { number: 13, text: "Wahrhaftige Worte gefallen dem König; / er liebt es, wenn jemand ehrlich ist." },
      { number: 14, text: "Der Zorn des Königs ist ein Bote des Todes, / doch ein weiser Mann wendet ihn ab." },
      { number: 15, text: "Das freundliche Gesicht eines Königs ist Leben; / seine Gunst ist wie eine Wolke, die im Frühjahr Regen bringt." },
      { number: 16, text: "Weisheit zu erwerben ist viel besser als Gold, / Verstand zu bekommen ist mehr als alles Silber wert." },
      { number: 17, text: "Die Straße der Ehrlichen heißt: Meide das Böse! / Wer das beachtet, bewahrt sein Leben." },
      { number: 18, text: "Hochmut kommt vor dem Fall / und Stolz vor dem Sturz." },
      { number: 19, text: "Besser bescheiden bei Armen zu sein, / als mit Überheblichen Beute zu teilen." },
      { number: 20, text: "Wer auf das Wort achtet, findet das Gute. / Glücklich der Mensch, der Jahwe vertraut!" },
      { number: 21, text: "Ein weiser Mensch ist angesehen, / und Anmut in der Sprache fördert Überzeugungskraft." },
      { number: 22, text: "Der Verstand ist eine Lebensquelle für den, der ihn hat; / Dumme werden durch ihre Dummheit bestraft." },
      { number: 23, text: "Ein Weiser redet mit Verstand, / das ist seinem Lehren förderlich." },
      { number: 24, text: "Freundliche Worte sind wie Honig, / süß für die Seele und für den Körper gesund." },
      { number: 25, text: "Mancher Weg erscheint dem Menschen recht, / doch am Ende führt er in den Tod." },
      { number: 26, text: "Der Hunger treibt den Menschen an, / er arbeitet, um essen zu können." },
      { number: 27, text: "Ein böser Mensch gräbt Unheil aus, / und auf seinen Lippen brennt es wie Feuer." },
      { number: 28, text: "Ein falscher Mensch sät überall Streit, / ein Verleumder verfeindet Freunde." },
      { number: 29, text: "Der Verbrecher verführt seinen Freund / und bringt ihn auf einen schlechten Weg." },
      { number: 30, text: "Wer mit den Augen zwinkert, führt Böses im Schild; / wer die Lippen verzieht, hat es schon getan." },
      { number: 31, text: "Graues Haar ist ein prächtiger Schmuck, / gefunden auf dem Weg der Gerechtigkeit." },
      { number: 32, text: "Geduld bringt weiter als Heldentum; / sich zu beherrschen ist besser, als Städte zu erobern." },
      { number: 33, text: "Im Gewandbausch wirft man das Los, / doch die Entscheidung kommt von Jahwe." },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Besser trockenes Brot und Einigkeit / als ein großes Festmahl und Streit." },
      { number: 2, text: "Ein kluger Diener wird Herr über einen missratenen Sohn / und teilt mit den Brüdern das Erbe." },
      { number: 3, text: "Der Tiegel prüft Silber, der Ofen das Gold; / doch Jahwe ist es, der die Herzen prüft." },
      { number: 4, text: "Ein Bösewicht hört auf böse Reden, / ein Lügner schenkt dem Verleumder Gehör." },
      { number: 5, text: "Wer Arme verspottet, verhöhnt deren Schöpfer; / und wer sich über Unglück freut, der bleibt nicht ungestraft." },
      { number: 6, text: "Der Alten Schmuck sind Enkelkinder, / der Kinder Stolz sind ihre Väter." },
      { number: 7, text: "Zum Dummen passt die vornehme Sprache nicht; / und die Lüge nicht zum geachteten Mann." },
      { number: 8, text: "Bestechung ist wie ein Zauberstein für den, der sie übt, / wohin er sich wendet, hat er Erfolg." },
      { number: 9, text: "Wer nach Liebe sucht, deckt Vergehen zu, / doch wer die Sache aufrührt, vertreibt den Freund." },
      { number: 10, text: "Eine Rüge trifft einen Verständigen mehr / als hundert Schläge einen Narren." },
      { number: 11, text: "Nur Aufruhr will der Böse, / doch ein strenger Gerichtsbote wird ihm geschickt." },
      { number: 12, text: "Besser einer Bärin begegnen, der die Jungen geraubt sind, / als einem Narren mit seinem Unverstand." },
      { number: 13, text: "Wer Gutes mit Bösem vergilt, / bei dem bleibt das Unheil ein ständiger Gast." },
      { number: 14, text: "Der Anfang eines Streits ist wie ein Wasserdurchbruch. / Hör auf, bevor der Prozess beginnt!" },
      { number: 15, text: "Den Schuldigen gerecht zu sprechen und den Gerechten für schuldig zu erklären, / beides verabscheut Jahwe." },
      { number: 16, text: "Was soll das Geld in des Dummen Hand? / Kann er Weisheit kaufen ohne Verstand?" },
      { number: 17, text: "Ein Freund steht immer zu dir, / wie ein Bruder ist er dir in der Not." },
      { number: 18, text: "Wer mit Handschlag für die Schulden eines anderen bürgt, / vermisst wohl seinen Verstand." },
      { number: 19, text: "Wer Streit liebt, liebt die Sünde; / wer sein Tor zu hoch baut, führt seinen Einsturz herbei." },
      { number: 20, text: "Ein hinterhältiger Mensch findet kein Glück; / ins Unheil stürzt, wer sich beim Reden verstellt." },
      { number: 21, text: "Hat jemand einen Dummkopf zum Sohn, dann hat er auch Kummer; / der Vater eines Narren freut sich nicht." },
      { number: 22, text: "Ein frohes Herz tut dem Körper wohl, / ein zerschlagener Geist trocknet ihn aus." },
      { number: 23, text: "Der Gottlose nimmt heimlich Geschenke an, / um die Wege des Rechts zu umgehen." },
      { number: 24, text: "Der Verständige hat die Weisheit vor Augen, / doch für den Dummen liegt sie am Ende der Welt." },
      { number: 25, text: "Ein dummer Sohn macht seinem Vater Verdruss; / und Kummer seiner Mutter, die ihn geboren hat." },
      { number: 26, text: "Eine Geldstrafe für den Unschuldigen ist nicht gut, / doch Edelleute schlagen zu lassen, ist gegen alles Recht." },
      { number: 27, text: "Wer Einsicht hat, spart sich die Worte, / wer sich beherrschen kann, zeigt seinen Verstand." },
      { number: 28, text: "Selbst ein Dummkopf wird für weise gehalten, wenn er schweigt, / für vernünftig, wenn er seine Lippen schließt." },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Wer sich absondert, geht nur den eigenen Wünschen nach, / gegen jede Einsicht wehrt er sich." },
      { number: 2, text: "Ein Dummkopf will die Sache nicht verstehen, / er will nur zeigen, was er meint." },
      { number: 3, text: "Mit Gottlosen kommt Verachtung / und mit der Schande die Schmach." },
      { number: 4, text: "Die Worte eines Menschen können tiefe Wasser sein, / ein sprudelnder Bach, eine Quelle der Weisheit." },
      { number: 5, text: "Es ist nicht gut, Partei für den Schuldigen zu nehmen / und dem Gerechten sein Recht zu verweigern." },
      { number: 6, text: "Die Reden eines Narren stiften Streit, / und sein Mund schreit, bis er Prügel bekommt." },
      { number: 7, text: "Der Mund des Narren ist sein Untergang, / seine Lippen bringen ihn zu Fall." },
      { number: 8, text: "Die Worte des Verleumders sind wie Leckerbissen; / man verschlingt sie mit großem Appetit." },
      { number: 9, text: "Wer seine Arbeit nachlässig tut, / ist wie einer, der alles zerstört." },
      { number: 10, text: "Wie ein fester Turm ist der Name Jahwes, / der Gerechte läuft zu ihm und ist in Sicherheit." },
      { number: 11, text: "Sein Vermögen hält der Reiche für eine sichere Stadt, / in seiner Einbildung ist es ein verlässlicher Schutz." },
      { number: 12, text: "Vor dem Sturz will mancher hoch hinaus, / doch der Ehre geht Demut voraus." },
      { number: 13, text: "Wer Antwort gibt, bevor er zuhört, / ist dumm und macht sich lächerlich." },
      { number: 14, text: "Der Mut eines Menschen überwindet die Krankheit, / doch wer hilft einem lebensmüden Geist?" },
      { number: 15, text: "Ein verständiger Mensch erweitert sein Wissen, / spitzt die Ohren und lernt stets dazu." },
      { number: 16, text: "Geschenke öffnen viele Türen, / selbst zu den Großen geleiten sie dich." },
      { number: 17, text: "Wer als Erster aussagt, hat scheinbar Recht, / doch dann kommt sein Gegner und stellt es in Frage." },
      { number: 18, text: "Das Los beendet den Streit / und bringt die Mächtigen auseinander." },
      { number: 19, text: "Ein getäuschter Bruder ist wie eine verschlossene Burg, / wie ein Festungsriegel der Streit mit ihm." },
      { number: 20, text: "Von der Frucht des Mundes wird der Körper satt, / vom Erfolg der Lippen kann man leben." },
      { number: 21, text: "Die Zunge hat Macht über Leben und Tod; / wer sie gut nutzt, genießt ihre Frucht." },
      { number: 22, text: "Wer seine Frau gefunden hat, hat Gutes gefunden / und dazu das Gefallen Jahwes." },
      { number: 23, text: "Der Arme muss bescheiden fragen, / der Reiche antwortet hart." },
      { number: 24, text: "Viele Gefährten gefährden dich, / ein echter Freund ist treuer als ein Bruder." },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Besser arm und ehrlich sein, / als ein Lügner und ein Trottel." },
      { number: 2, text: "Unbedachter Eifer ist nicht gut, / wer es allzu eilig hat, tritt fehl." },
      { number: 3, text: "Durch eigene Dummheit verdirbt man den Plan, / doch wütend ist man auf Jahwe." },
      { number: 4, text: "Besitz vermehrt die Zahl der Freunde, / doch den Armen verlässt selbst sein Freund." },
      { number: 5, text: "Ein falscher Zeuge bleibt nicht ungestraft; / wer Lügen vorbringt, kommt nicht davon." },
      { number: 6, text: "Viele schmeicheln dem, der Einfluss hat, / und jeder will der Freund des Freigebigen sein." },
      { number: 7, text: "Den Armen hassen alle Verwandten, / und seine Bekannten meiden ihn. / Und er jagt leeren Versprechungen nach." },
      { number: 8, text: "Bilde deinen Verstand, dann tust du dir Gutes; / folg deiner Einsicht, dann findest du Glück!" },
      { number: 9, text: "Ein falscher Zeuge bleibt nicht ungestraft; / wer Lügen vorbringt, hat sein Leben verspielt." },
      { number: 10, text: "Wohlstand steht einem Dummen nicht an; / und keinem Sklaven die Macht über Fürsten." },
      { number: 11, text: "Ein Mensch, der Einsicht hat, regt sich nicht auf, / es ehrt ihn, dass er Verfehlungen vergibt." },
      { number: 12, text: "Der Zorn des Königs ist wie Löwengebrüll, / doch seine Gunst ist wie Tau auf dem Gras." },
      { number: 13, text: "Ein Verhängnis für den Vater ist der dumme Sohn; / und eine nörgelnde Frau ist wie ein tropfendes, undichtes Dach." },
      { number: 14, text: "Haus und Habe kann man erben, / doch eine verständige Frau kommt von Jahwe." },
      { number: 15, text: "Faulheit führt zum Tiefschlaf, / wer lässig ist, muss hungern." },
      { number: 16, text: "Wer Gottes Weisung beachtet, der achtet auf sein Leben, / doch wer sich gehen lässt, kommt um." },
      { number: 17, text: "Wer Bedürftigen hilft, leiht Jahwe; / er wird ihm seine Wohltat vergelten." },
      { number: 18, text: "Deinen Sohn erziehe streng, solange noch Hoffnung ist; / lass ihn nicht in sein Verderben laufen." },
      { number: 19, text: "Wer im Jähzorn handelt, trägt seine Strafe davon; / greifst du ein, machst du es noch schlimmer." },
      { number: 20, text: "Hör auf den Rat und nimm die Zurechtweisung an, / dann bist du am Ende ein weiser Mann." },
      { number: 21, text: "Viele Dinge nimmt ein Mensch sich vor, / doch zustande kommt der Ratschluss Jahwes." },
      { number: 22, text: "Was einen Menschen wertvoll macht, ist seine Güte; / und besser arm sein, als ein verlogener Mann." },
      { number: 23, text: "Jahwe zu fürchten ist gut zum Leben: / Satt und zufrieden verbringt man die Nacht / und wird nicht von Unglück berührt." },
      { number: 24, text: "Greift der Faule mit der Hand in die Schüssel, / bringt er sie nicht zurück in den Mund." },
      { number: 25, text: "Schlägt man den Spötter, wird ein Unerfahrener klug; / weist man den Verständigen zurecht, lernt er daraus." },
      { number: 26, text: "Wer den Vater misshandelt, die Mutter verjagt, / ist ein verkommener, schändlicher Sohn." },
      { number: 27, text: "Hör dir die Mahnung gar nicht erst an, mein Sohn, / wenn du doch von der Lehre abweichen willst." },
      { number: 28, text: "Ein ehrloser Zeuge verspottet das Recht, / und Gottlose finden am Unrecht Geschmack." },
      { number: 29, text: "Für Spötter stehen Gerichte bereit / und Prügel für den Rücken der Trottel." },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Der Wein macht Spötter, das Bier Krakeeler. / Wer sich betrinkt, der kann nicht weise sein." },
      { number: 2, text: "Das Drohen des Königs gleicht dem Brüllen des Löwen. / Wer seinen Zorn erregt, hat sein Leben verwirkt." },
      { number: 3, text: "Vom Streit zu lassen, ehrt einen Mann, / doch jeder Trottel stürzt sich hinein." },
      { number: 4, text: "Im Herbst mag der Faule nicht pflügen, / und wenn er ernten will, findet er nichts." },
      { number: 5, text: "Guter Rat im Herzen des Menschen ist wie ein tiefes Wasser, / doch ein kluger Mann schöpft daraus." },
      { number: 6, text: "Viele loben ihre eigene Frömmigkeit, / doch wer findet wirklich einen verlässlichen Mann?" },
      { number: 7, text: "Wer rechtschaffen lebt, wie Gott es gefällt: / Glücklich die Kinder, die er hinterlässt!" },
      { number: 8, text: "Ein König, der auf dem Richterstuhl sitzt, / findet mit den Augen jeden Bösen heraus." },
      { number: 9, text: "Wer kann schon sagen: \"Mein Gewissen ist rein, / ich bin frei von jeder Schuld\"?" },
      { number: 10, text: "Zweierlei Maß und zweierlei Gewicht, / beides verabscheut Jahwe." },
      { number: 11, text: "Schon ein junger Mann zeigt an seinen Taten, / ob sein Handeln rein und redlich ist." },
      { number: 12, text: "Das Ohr, das hört, das Auge, das sieht, / Jahwe hat beide gemacht." },
      { number: 13, text: "Liebst du den Schlaf, so bist du bald arm. / Mach die Augen auf, dann hast du zu essen." },
      { number: 14, text: "\"Schlecht, schlecht!\" sagt der Käufer, / doch wenn er weggeht, gibt er mit dem Schnäppchen an." },
      { number: 15, text: "Es gibt Gold und viele Perlen – der kostbarste Schmuck ist ein verständiges Wort." },
      { number: 16, text: "Nimm sein Gewand, denn er hat für den Fremden gebürgt, / pfände ihn aus diesem Grund selbst." },
      { number: 17, text: "Süß schmeckt ihm das Brot des Betrugs, / doch danach hat er den Mund voller Kies." },
      { number: 18, text: "Durch Beratung haben Pläne Bestand. / Zieh nur mit weiser Überlegung in den Kampf!" },
      { number: 19, text: "Wer als Verleumder umherzieht, gibt Anvertrautes preis. / Lass dich nicht mit einem Schwätzer ein!" },
      { number: 20, text: "Wer Vater oder Mutter verflucht, / dessen Lampe erlischt in Finsternis." },
      { number: 21, text: "Wer das Erbe hastig an sich reißt, / wird am Ende nicht gesegnet sein." },
      { number: 22, text: "Sag nicht: Ich will das Böse vergelten! / Vertraue Jahwe, er wird dir helfen." },
      { number: 23, text: "Zweierlei Gewicht und falsche Waage, / beides verabscheut Jahwe." },
      { number: 24, text: "Von Jahwe sind des Mannes Schritte gelenkt. / Was versteht der Mensch von seinem Weg?" },
      { number: 25, text: "Wer vorschnell ruft \"Geweiht!\" und dann erst sein Gelübde bedenkt, / ist schon in die Falle getappt." },
      { number: 26, text: "Ein weiser König sondert die Gesetzlosen aus / und führt das Dreschrad* über sie hin.", footnotes: ["Dreschrad. Das Rad des Dreschwagens, der auf der Tenne von Tieren im Kreis über das Getreide gezogen wurde, um das Korn von der Hülse zu trennen, siehe Jesaja 28,27-28."] },
      { number: 27, text: "Der Geist des Menschen ist ein Licht Jahwes, / er durchforscht des Menschen Innerstes." },
      { number: 28, text: "Gnade und Treue behüten den König, / ja durch Güte stützt er seinen Thron." },
      { number: 29, text: "Der Stolz der Jungen ist ihre Kraft, / der Schmuck der Alten das graue Haar." },
      { number: 30, text: "Blutige Striemen bessern den Bösen / und Schläge des Menschen Inneres." },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Wie ein Wasserlauf ist das Herz des Königs in Jahwes Hand; / er lenkt es, wohin er auch will." },
      { number: 2, text: "Der Mensch hält alles, was er tut, für gut, / doch Jahwe prüft die Motive." },
      { number: 3, text: "Gerechtigkeit und rechtes Tun sind Jahwe lieber als geschlachtete Opfer." },
      { number: 4, text: "Stolze Augen und Überheblichkeit, das Licht der Gottlosen, sind Sünde." },
      { number: 5, text: "Überlegung und Fleiß bringen guten Gewinn, / doch Hast und Eile nichts als Verlust." },
      { number: 6, text: "Durch Betrug erworbener Reichtum / ist wie ein verwehter Dunst, eine tödliche Falle." },
      { number: 7, text: "Gewalttat reißt die Gesetzlosen weg, / denn sie weigern sich, das Richtige zu tun." },
      { number: 8, text: "Verschlungen ist der Weg des Schuldigen, / der Gerechte geht den geraden Weg." },
      { number: 9, text: "Besser auf dem Flachdach zu wohnen / als mit einer zänkischen Frau zusammen im Haus." },
      { number: 10, text: "Ein böser Mensch hat Böses im Sinn, / kein Mitgefühl für den Nächsten." },
      { number: 11, text: "Bestraft man den Spötter, lernt ein Unerfahrener davon; / belehrt man den Weisen, lernt er selbst daraus." },
      { number: 12, text: "Ein Gerechter* achtet auf das gottlose Haus. / Er stürzt die Gottlosen ins Unglück.", footnotes: ["Gerechter. Vielleicht ist damit Gott gemeint."] },
      { number: 13, text: "Wer sein Ohr vor dem Schrei des Schwachen verschließt, / bekommt auch keine Antwort, wenn er einmal ruft." },
      { number: 14, text: "Eine heimliche Gabe besänftigt den Zorn, / ein verborgenes Geschenk die heftige Wut." },
      { number: 15, text: "Der Gerechte freut sich, wenn Recht geschieht, / doch der Verbrecher wird in Schrecken versetzt." },
      { number: 16, text: "Ein Mensch, der vom Weg der Einsicht abirrt, / ruht bald in der Versammlung der Schatten." },
      { number: 17, text: "Wer die Festfreude liebt, wird dem Mangel verfallen; / wer aufwändig lebt, wird niemals reich." },
      { number: 18, text: "Der Schuldige zahlt das Lösegeld für den Gerechten, / der Betrüger muss für den Ehrlichen büßen." },
      { number: 19, text: "Besser in der Wüste hausen / als Ärger mit einer zänkischen Frau." },
      { number: 20, text: "Wertvolle Schätze und duftendes Öl sind in der Wohnung des Weisen, / doch ein Dummer vergeudet es schnell." },
      { number: 21, text: "Wer nach Gerechtigkeit und Güte strebt, / findet Leben, Recht und Ehre." },
      { number: 22, text: "Ein Weiser erobert die Stadt der Starken / und stürzt das Bollwerk ihrer Sicherheit." },
      { number: 23, text: "Wer den Mund hält, / hält sich Probleme vom Hals." },
      { number: 24, text: "Der stolze Übermütige – man nennt ihn Spötter – spielt mit böser Überheblichkeit." },
      { number: 25, text: "Den Faulen bringen seine Wünsche um, / denn seine Hände wollen nichts tun." },
      { number: 26, text: "Es begehrt die Begierde den ganzen Tag, / doch der Gerechte gibt und kann großzügig sein." },
      { number: 27, text: "Das Opfer des Gottlosen verabscheut Jahwe, / besonders wenn er es für Schandtaten bringt." },
      { number: 28, text: "Ein falscher Zeuge geht zugrunde, / doch wer zuhört, redet mit Erfolg." },
      { number: 29, text: "Der Gottlose macht ein freches Gesicht, / der Gerechte hat einen sicheren Gang." },
      { number: 30, text: "Keine Weisheit, kein Verstand, / kein Rat besteht vor Jahwe." },
      { number: 31, text: "Das Pferd wird gerüstet für den Tag der Schlacht, / doch der Sieg ist die Sache Jahwes." },
    ] },
    { number: 22, verses: [
      { number: 1, text: "Ein guter Name ist besser als großer Besitz, / Beliebtheit besser als Silber und Gold." },
      { number: 2, text: "Der Reiche und der Arme begegnen sich, / der sie beide schuf, ist Jahwe." },
      { number: 3, text: "Der Kluge sieht das Unglück voraus und bringt sich in Sicherheit, / der Unerfahrene geht weiter und kommt zu Fall." },
      { number: 4, text: "Der Lohn von Demut und Furcht vor Jahwe / ist Reichtum, Ehre und erfülltes Leben." },
      { number: 5, text: "Der Weg des Falschen ist voll Haken und Schlingen, / wer sein Leben liebt, meidet ihn." },
      { number: 6, text: "Gewöhne den Jungen an seinen Weg, / dann bleibt er auch im Alter dabei." },
      { number: 7, text: "Der Reiche hat die Armen in seiner Gewalt, / der Schuldner ist seines Gläubigers Sklave." },
      { number: 8, text: "Wer Unrecht sät, wird Unheil ernten, / der Stock beendet seinen Übermut." },
      { number: 9, text: "Wer großzügig ist, wird gesegnet sein, / denn er teilt sein Brot mit den Armen." },
      { number: 10, text: "Vertreibe den Spötter, dann zieht auch der Zank fort, / das Streiten und Schimpfen hört auf." },
      { number: 11, text: "Wer ein reines Gewissen liebt und gewinnend reden kann, / den nimmt der König zum Freund." },
      { number: 12, text: "Die Augen Jahwes bewachen das Erkennen, / doch die Worte des Falschen fegt er hinweg." },
      { number: 13, text: "Der Faule sagt: Ein Löwe ist draußen, / der bringt mich um, mitten auf dem Platz." },
      { number: 14, text: "Eine tiefe Grube ist der Mund der fremden Frau, / wen Jahwe strafen will, der fällt hinein." },
      { number: 15, text: "Hat ein Kind nur Dummheiten im Kopf, / entfernt man sie durch die Rute der Zucht." },
      { number: 16, text: "Wer den Armen unterdrückt, mehrt dessen Besitz; / wer dem Reichen gibt, verschafft ihm Verarmung*.", footnotes: ["Verarmung. Gemeint ist vielleicht, dass Bedrückung die Energie und Arbeitsleistung des Armen vermehrt, und Geschenke beim Reichen die Verschwendungssucht."] },
      { number: 17, text: "Hör mir zu! Vernimm die Worte von Weisen / und nimm dir mein Wissen zu Herzen!", heading: "Dreißig weise Sprüche" },
      { number: 18, text: "Es ist gut, wenn du sie auswendig lernst, / damit du sie jederzeit aufsagen kannst." },
      { number: 19, text: "Ich belehre dich heute, / damit du Jahwe vertraust." },
      { number: 20, text: "Dreißig von diesen Lehren schrieb ich dir auf, / Ratschläge, gut und begründet." },
      { number: 21, text: "Sie zeigen dir, wie zuverlässig Wahrheit ist, / damit du dem, der dich schickte, eine verlässliche Antwort bringst .(1)" },
      { number: 22, text: "Beraube nicht den Schwachen, der sich nicht wehren kann, / und benachteilige nicht den Hilflosen vor Gericht." },
      { number: 23, text: "Jahwe schützt die Schutzlosen. / Wer sie beraubt, dem raubt er das Leben.(2)" },
      { number: 24, text: "Lass dich nicht mit einem Zornigen ein, / und vom Hitzkopf halte dich fern." },
      { number: 25, text: "Sonst gewöhnst du dich an seine Unart / und bringst dich selber zu Fall.(3)" },
      { number: 26, text: "Sei nicht unter denen, die sich durch Handschlag verpflichten, / die Bürgschaft leisten für fremde Schuld." },
      { number: 27, text: "Denn wenn du dann nicht bezahlen kannst, / pfändet man selbst dein Bett.(4)" },
      { number: 28, text: "Verrücke die uralte Grenze nicht, / die deine Väter dem Grundstück gesetzt.(5)" },
      { number: 29, text: "Siehst du einen, der tüchtig ist in seinem Beruf – Königen wird er dienen / und nicht irgendwelchen, die niemand kennt.(6)" },
    ] },
    { number: 23, verses: [
      { number: 1, text: "Wenn du bei hohen Herren zu Tische sitzt, / bedenke immer, wen du vor dir hast." },
      { number: 2, text: "Setz dir ein Messer an die Kehle, / wenn du allzu gierig bist!" },
      { number: 3, text: "Und gib acht bei ihren Leckerbissen, / und lass dich durch sie nicht betrügen.(7)" },
      { number: 4, text: "Müh dich nicht ab, es zu Reichtum zu bringen, / aus eigener Einsicht lass die Finger davon!" },
      { number: 5, text: "Denn eh du dich versiehst, hat er Flügel bekommen / und fliegt wie ein Adler fort durch die Luft.(8)" },
      { number: 6, text: "Vom Geizhals nimm keine Einladung an, / seine Leckerbissen begehre nicht!" },
      { number: 7, text: "Denn er hat alles abgezählt. / \"Iss und trink!\", sagt er zu dir, / aber im Grunde gönnt er dir nichts." },
      { number: 8, text: "Den Bissen, den du gegessen hast, musst du erbrechen, / und vergeudet ist jedes freundliche Wort.(9)" },
      { number: 9, text: "Sprich nicht zu den Ohren eines Toren, / denn er verachtet deinen guten Rat.(10)" },
      { number: 10, text: "Verrücke die uralte Grenze nicht, / auch nicht auf Kosten hilfloser Waisen." },
      { number: 11, text: "Denn sie haben einen mächtigen Beistand, / der ihren Prozess gegen dich führt.(11)" },
      { number: 12, text: "Öffne dein Herz für jede Ermahnung, / dein Ohr für verständiges Reden.(12)" },
      { number: 13, text: "Erspare dem Knaben die Züchtigung nicht! / Eine Tracht Prügel bringt ihn nicht um." },
      { number: 14, text: "Du schlägst ihn mit der Rute, / doch du rettest sein Leben.(13)" },
      { number: 15, text: "Mein Sohn, wenn du klug und einsichtig wirst, / ist das eine herzliche Freude für mich." },
      { number: 16, text: "Und mein Inneres wird jubeln, / wenn Ehrliches von deinen Lippen kommt.(14)" },
      { number: 17, text: "Ereifere dich nicht über die Sünder, / sondern bemühe dich täglich, Jahwe zu ehren!" },
      { number: 18, text: "Denn das Ende kommt ja noch, / und dann verlierst du deine Hoffnung nicht.(15)" },
      { number: 19, text: "Höre mein Sohn und sei klug, / und bleib auf dem geraden Weg!" },
      { number: 20, text: "Halte dich von den Weinsäufern fern / und von denen, die im Fleischgenuss schwelgen." },
      { number: 21, text: "Denn Säufer und Schlemmer werden arm, / und Schläfrigkeit kleidet in Lumpen.(16)" },
      { number: 22, text: "Hör auf deinen Vater, der dich gezeugt hat, / und verachte deine Mutter nicht, auch wenn sie alt geworden ist." },
      { number: 23, text: "Lass dir die Wahrheit etwas kosten, / auch Weisheit, Selbstbeherrschung und Verstand! / Und gib das alles nie wieder her!" },
      { number: 24, text: "Laut jubelt der Vater eines Gerechten; / er freut sich über einen verständigen Sohn." },
      { number: 25, text: "Mögen auch deine Eltern sich freuen, / möge jubeln die, die dich gebar.(17)" },
      { number: 26, text: "Gib mir dein Herz, mein Sohn, / und lass dir meine Wege gefallen." },
      { number: 27, text: "Denn die Hure ist wie ein tiefer Schacht, / die Fremde wie ein gefährliches Loch." },
      { number: 28, text: "Sie lauert dir auf wie ein Räuber / und vermehrt die Zahl der untreuen Männer.(18)" },
      { number: 29, text: "Wer hat Ach und wer hat Weh? / Wer hat Streit und wer jammert herum? / Wer lässt sich grundlos schlagen, / und wer hat glasige Augen?" },
      { number: 30, text: "Die bis spät beim Weine sitzen, / die kommen, um den Mischwein zu kosten." },
      { number: 31, text: "Sieh den Wein nicht an, wie er schimmert, / wie er so rot im Becher funkelt; / wie glatt er durch die Kehle rinnt!" },
      { number: 32, text: "Am Ende beißt er wie eine Schlange, / wie eine Viper spritzt er sein Gift." },
      { number: 33, text: "Dann siehst du seltsame Dinge / und redest dummes Zeug." },
      { number: 34, text: "Du fühlst dich wie auf stürmischer See, / als ob du im Mastkorb eines Schiffes liegst." },
      { number: 35, text: "\"Man hat mich geschlagen, doch es tat mir nicht weh; / man hat mich verprügelt, ich merkte es nicht. / Wie werde ich nur wieder wach? / Ich brauche einen Schluck, / ich muss wieder hin!\"(19)" },
    ] },
    { number: 24, verses: [
      { number: 1, text: "Beneide keine bösen Menschen, / sei nicht begierig, bei ihnen zu sein!" },
      { number: 2, text: "Denn sie haben nur Verbrechen im Sinn / und reden nur, um Schaden zu tun.(20)" },
      { number: 3, text: "Durch Weisheit wird ein Haus gebaut, / durch Verstand gewinnt es Bestand;" },
      { number: 4, text: "durch Klugheit füllen sich die Räume / mit wertvollem und schönem Gut.(21)" },
      { number: 5, text: "Nur ein kluger Mann ist wirklich stark, / durch Wissen lenkt er seine Kraft." },
      { number: 6, text: "Nur durch kluge Maßnahmen gewinnst du die Schlacht / und durch viele Ratgeber den Sieg.(22)" },
      { number: 7, text: "Die Weisheit ist dem Narren zu hoch, / im Rat macht er den Mund nicht auf.(23)" },
      { number: 8, text: "Wer nur darauf aus ist, Böses zu tun, / den nennt man einen Bösewicht." },
      { number: 9, text: "Auch die Intrigen eines Dummen sind Sünde, / und ein Spötter ist ein abscheulicher Mensch.(24)" },
      { number: 10, text: "Bist du lässig am gewöhnlichen Tag, / versagt deine Kraft auch in der Bedrängnis.(25)" },
      { number: 11, text: "Rette die, die man zum Tod hinschleppt, / und die zur Hinrichtung wanken, o halte sie zurück!" },
      { number: 12, text: "Wenn du sagst: \"Wir haben nichts davon gewusst!\", / dann sollst du wissen: Der dir ins Herz sieht, weiß Bescheid, / der auf dich achtet, hat dich durchschaut! / Jedem vergilt er, was er verdient.(26)" },
      { number: 13, text: "Iss Honig, mein Sohn, / denn er ist gesund / und ein Genuss für den Gaumen." },
      { number: 14, text: "Doch Weisheit ist heilsam für dein Leben. / Hast du sie gefunden, dann hast du auch Zukunft, / und deine Hoffnung schwindet nicht.(27)" },
      { number: 15, text: "Bringe nicht einen ehrlichen Mann / um Haus und Hof, du Gottloser," },
      { number: 16, text: "denn der Gerechte fällt sieben Mal und steht doch wieder auf, / aber Gottlose versinken im Unglück.(28)" },
      { number: 17, text: "Fällt dein Feind, so freue dich nicht, / frohlocke nicht, wenn er stürzt," },
      { number: 18, text: "damit es nicht Jahwe missfällt / und er deinen Feind verschont.(29)" },
      { number: 19, text: "Reg dich nicht auf über die Bösen, / beneide die Gottlosen nicht." },
      { number: 20, text: "Denn der Böse hat keine Zukunft, / und die Leuchte der Gottlosen erlischt.(30)" },
      { number: 21, text: "Ehre Jahwe und achte den König, mein Sohn! / Lass dich nicht mit Aufrührern ein!" },
      { number: 22, text: "Denn plötzlich trifft sie das Verderben, / von beiden kommt es über sie." },
      { number: 23, text: "Auch die folgenden Sprüche stammen von Weisen:Parteilichkeit im Gericht ist niemals gut.", heading: "Weitere Sprüche von Weisen" },
      { number: 24, text: "Wer zu dem Schuldigen sagt: \"Du bist gerecht\", / den verfluchen die Leute, ganze Völker verwünschen ihn." },
      { number: 25, text: "Doch denen, die gerecht entscheiden, geht es gut, / über sie kommt Segen und Glück." },
      { number: 26, text: "Eine treffende Antwort ist wie ein Kuss auf die Lippen." },
      { number: 27, text: "Zuerst tu deine Arbeit draußen und bestelle dein Feld! / Danach erst baue dein Haus!" },
      { number: 28, text: "Tritt nie als falscher Zeuge gegen jemand auf, / betrüge nicht mit deinen Worten!" },
      { number: 29, text: "Sag nicht: \"Wie du mir, so ich dir! / Was er mir antut, zahl ich ihm heim!\"" },
      { number: 30, text: "Ich kam am Feld eines Faulen vorbei, / am Weinberg eines Mannes ohne Verstand." },
      { number: 31, text: "Sieh da, er war ganz überwuchert von Disteln, / seine Fläche mit Unkraut bedeckt, / seine Mauer eingestürzt." },
      { number: 32, text: "Ich schaute hin und nahm es zu Herzen, / ich sah es und zog eine Lehre daraus:" },
      { number: 33, text: "Nur noch ein wenig Schlaf, / nur noch ein bisschen Schlummer; / nur noch ein wenig liegen, die Hände gefaltet;" },
      { number: 34, text: "wie schnell kommt dann die Armut ins Haus; / wie schnell überfällt dich die Not!" },
    ] },
    { number: 25, verses: [
      { number: 1, text: "Auch die folgenden Sprichwörter stammen von Salomo. Sie wurden gesammelt von Männern des Königs Hiskija von Juda.", heading: "25-29: Gesammelte Weisheit\nWeitere Sprichwörter Salomos" },
      { number: 2, text: "Ist es Gottes Ehre, eine Sache zu verbergen, / so ist es der Könige Ehre, eine Sache zu erforschen." },
      { number: 3, text: "Der Himmel an Höhe, die Erde an Tiefe, und die Gedanken der Könige – unerforschlich sind sie." },
      { number: 4, text: "Entferne die Schlacken aus dem Silber, / dann gelingt dem Goldschmied ein Schmuckstück." },
      { number: 5, text: "Entferne den Gottlosen vom König, / dann regiert er gerecht und seine Herrschaft besteht." },
      { number: 6, text: "Tritt vor dem König bescheiden auf, / und stell dich nicht an den Platz der Großen." },
      { number: 7, text: "Es ist besser, man ruft dich auf den höheren Platz, / als dass man dich vor Edlen herabsetzt.Was du mit deinen Augen erblickt hast," },
      { number: 8, text: "bringe nicht so schnell zum Gericht! / Denn was willst du machen, wenn dich dein Nächster beschämt?" },
      { number: 9, text: "Trag deinen Streit mit deinem Mitmenschen aus, / aber gib nicht das Geheimnis eines anderen preis;" },
      { number: 10, text: "sonst verachtet dich jeder, der davon hört, / und du behältst einen üblen Ruf." },
      { number: 11, text: "Wie goldene Äpfel auf silbernen Schalen / ist ein rechtes Wort zur richtigen Zeit." },
      { number: 12, text: "Wie ein goldener Ring, wie feinster Schmuck / ist ein weiser Mahner für ein offenes Ohr." },
      { number: 13, text: "Wie kühlender Schnee am Erntetag, / so ist ein treuer Bote für den, der ihn schickt: / eine erfrischende Freude für seinen Herrn." },
      { number: 14, text: "Wie Wolken und Wind, aber kein Regen, / ist jemand, der Versprechungen macht, sie aber nicht hält." },
      { number: 15, text: "Mit Geduld wird ein Vorgesetzter umgestimmt, / denn eine sanfte Zunge kann den Widerstand* brechen.", footnotes: ["Widerstand. Wörtlich: Knochen."] },
      { number: 16, text: "Hast du Honig gefunden, iss nur so viel dir bekommt, / sonst wirst du ihn satt und erbrichst." },
      { number: 17, text: "Mach dich selten im Haus deines Nächsten, / sonst wird er dich satt und verabscheut dich." },
      { number: 18, text: "Eine Keule, ein Schwert, ein spitzer Pfeil / ist ein falscher Zeuge für seinen Nächsten." },
      { number: 19, text: "Ein brüchiger Zahn und ein schlotternder Fuß, / so ist ein treuloser Mensch in der Zeit der Not." },
      { number: 20, text: "Wenn einer sich auszieht bei Frost, / wenn jemand Essig auf Natron gießt*, / so ist es, wenn man lustige Lieder vor einem Traurigen singt.", footnotes: ["auf Natron gießt. Es gibt eine heftige Reaktion, aber das Natron wird dadurch unbrauchbar."] },
      { number: 21, text: "Wenn dein Feind hungrig ist, gib ihm zu essen, / wenn er Durst hat, gib ihm zu trinken;" },
      { number: 22, text: "so sammelst du glühende Kohlen auf seinen Kopf*, / und Jahwe vergilt es dir.*", footnotes: ["Kohlen auf seinen Kopf. Dann wird es ihm leid, einem anderen feind zu sein.", "Wird im Neuen Testament von Paulus zitiert: Römer 12,20."] },
      { number: 23, text: "Nordwind bringt Regen / und Klatsch ein verdrießliches Gesicht." },
      { number: 24, text: "Besser auf dem Flachdach zu wohnen / als mit einer zänkischen Frau zusammen im Haus." },
      { number: 25, text: "Kühles Wasser für eine durstige Kehle / ist eine gute Nachricht aus fernem Land." },
      { number: 26, text: "Eine trübe Quelle, ein verdorbener Brunnen, / so ist ein Gerechter, der vor einem Gottlosen wankt." },
      { number: 27, text: "Zu viel Honig essen ist nicht gut, / zuviel Ehre bekommt einem nicht*.", footnotes: ["bekommt einem nicht. Der hebräische Text des zweiten Teils ist nicht sicher zu deuten."] },
      { number: 28, text: "Wie eine Stadt mit zerstörter Mauer / ist ein Mann, der sich nicht beherrschen kann." },
    ] },
    { number: 26, verses: [
      { number: 1, text: "Wie Schnee zum Sommer und Regen zur Ernte / passt Ehre zum Dummkopf." },
      { number: 2, text: "Wie ein flatternder Spatz, eine Schwalbe im Flug, / so ist ein unverdienter Fluch: Er trifft nicht ein." },
      { number: 3, text: "Eine Peitsche fürs Pferd, ein Zaum für den Esel / und ein Stock auf den Rücken des Toren." },
      { number: 4, text: "Gib dem Toren keine Antwort, die seiner Dummheit entspricht, / sonst wirst du ihm gleich." },
      { number: 5, text: "Gib dem Dummkopf eine Antwort, die seine Torheit verdient, / sonst hält er sich für klug." },
      { number: 6, text: "Wer Botschaft durch einen Dummkopf schickt, / hackt sich selbst die Füße ab und muss Bitteres schlucken." },
      { number: 7, text: "Schlaff hängen die Beine des Lahmen / und ein Weisheitsspruch im Mund des Dummen." },
      { number: 8, text: "Wer einem Dummen Ehre erweist, / verschnürt einen Stein in der Schleuder." },
      { number: 9, text: "Wie ein Dornzweig in der Hand des Betrunkenen / ist ein Weisheitsspruch im Mund des Dummen." },
      { number: 10, text: "Wie ein Bogenschütze, der auf jeden schießt, / ist einer, der Narren und Strolche einstellt." },
      { number: 11, text: "Wie ein Hund zu seinem Erbrochenen umkehrt, / ist ein Narr, der seinen Unsinn wiederholt.*", footnotes: ["Wird im Neuen Testament von Petrus zitiert: 2. Petrus 2,22."] },
      { number: 12, text: "Kennst du einen, der sich selbst für weise hält? / Für einen Dummen ist mehr Hoffnung als für ihn." },
      { number: 13, text: "Der Faule sagt: \"Draußen läuft ein Löwe herum, / ein Junglöwe mitten auf dem Platz.\"" },
      { number: 14, text: "Die Tür dreht sich in der Angel / und der Faule im Bett." },
      { number: 15, text: "Greift der Faule mit der Hand in die Schüssel, / ist ihm die Mühe zu groß: Er bringt sie nicht zurück in den Mund." },
      { number: 16, text: "Ein Faulpelz hält sich für klüger / als sieben Sachverständige." },
      { number: 17, text: "Wer sich in Streit mischt, der ihn nichts angeht, / der packt einen streunenden Hund bei den Ohren." },
      { number: 18, text: "Wie ein Irrer, der mit Brandpfeilen schießt / und mit tödlichen Waffen hantiert," },
      { number: 19, text: "ist ein Mann, der seinen Nächsten betrügt / und dann sagt: \"Es war nur ein Scherz.\"" },
      { number: 20, text: "Wo kein Holz mehr ist, geht das Feuer aus; / ist der Verleumder fort, legt sich der Streit." },
      { number: 21, text: "Wie Kohlen die Glut und wie Holz das Feuer, / so schürt ein zänkischer Mann den Streit." },
      { number: 22, text: "Die Worte des Verleumders werden gierig geschluckt / und dringen sehr tief ein." },
      { number: 23, text: "Wie Silberglasur auf Tongeschirr / sind glatte Zungen und ein böses Herz." },
      { number: 24, text: "Ein gehässiger Mensch verstellt seine Worte, / doch im Inneren ist er falsch." },
      { number: 25, text: "Trau seinen schönen Worten nicht, / denn sieben Teufeleien hat er im Sinn." },
      { number: 26, text: "Mag Hass sich hinter Verstellung verbergen, / in der Versammlung wird die Bosheit durchschaut." },
      { number: 27, text: "Wer andern eine Grube gräbt, fällt selbst hinein. / Wer einen Stein hoch wälzt, auf den rollt er zurück." },
      { number: 28, text: "Eine falsche Zunge hasst ihre Opfer, / und ein schmeichelnder Mund verursacht den Sturz." },
    ] },
    { number: 27, verses: [
      { number: 1, text: "Rühme dich nicht des morgigen Tages, / denn du weißt nicht, was ein neuer Tag bringt." },
      { number: 2, text: "Mag ein anderer dich loben, doch nicht dein eigener Mund; / ein Fremder mag dich rühmen, doch nicht deine eigenen Lippen." },
      { number: 3, text: "Ein Stein ist schwer, Sand eine Last; / noch schwerer wiegt der Ärger, den man mit Dummen hat." },
      { number: 4, text: "Wut ist grausam und Zorn schäumt über, / doch wer besteht vor der Eifersucht?" },
      { number: 5, text: "Besser ein offener Tadel / als Liebe, die ängstlich schweigt." },
      { number: 6, text: "Treu gemeint sind die Schläge von dem, der dich liebt, / doch reichlich die Küsse des Hassers." },
      { number: 7, text: "Der Satte verachtet den besten Honig, / dem Hungrigen ist alles Bittere süß." },
      { number: 8, text: "Wie ein Vogel, der weit vom Nest weg fliegt, / ist ein Mensch, der seine Heimat verlässt." },
      { number: 9, text: "Salböl und Weihrauch erfreuen das Herz, / die Freundlichkeit des Freundes die bekümmerte Seele." },
      { number: 10, text: "Den Freund und deines Vaters Freund gib niemals auf! / Lauf nicht zu deinem Bruder, wenn du in Schwierigkeiten bist! / Besser ein Nachbar in der Nähe als ein Bruder in der Ferne." },
      { number: 11, text: "Werde weise, mein Sohn, und erfreue mein Herz, / damit ich den widerlegen kann, der mich beschimpft." },
      { number: 12, text: "Der Kluge sieht das Unglück voraus und bringt sich in Sicherheit; / der Unerfahrene geht weiter und kommt zu Fall." },
      { number: 13, text: "Nimm sein Gewand, denn er hat für den Fremden gebürgt; / pfände ihn aus diesem Grund selbst." },
      { number: 14, text: "Wer frühmorgens seinen Nächsten allzu laut grüßt, / dem wird es als Verwünschung ausgelegt." },
      { number: 15, text: "Ein tropfendes Dach, das am Regentag nervt, / gleicht sehr einer zänkischen Frau." },
      { number: 16, text: "Wer sie aufhalten will, / kann auch versuchen, den Wind festzuhalten / und Öl mit den Fingern zu greifen." },
      { number: 17, text: "Ein Messer wetzt das andere, / durch Umgang mit anderen bekommt man den Schliff." },
      { number: 18, text: "Wer den Feigenbaum hütet, bekommt die Feigen zu essen; / wer seinen Herrn beschützt, wird geehrt." },
      { number: 19, text: "Im Spiegel des Wassers erkennst du dein Gesicht, / im Spiegel deiner Gedanken dich selbst." },
      { number: 20, text: "Totenreich und Unterwelt werden nie satt, / auch die Augen des Menschen sehen niemals genug." },
      { number: 21, text: "Was der Tiegel für das Silber, / der Schmelzofen fürs Gold, / ist der Ruf für einen Mann." },
      { number: 22, text: "Wenn du den Dummkopf im Mörser zerstampfst, / wenn der Stößel ihn trifft wie die Körner, / seine Dummheit treibst du nicht aus." },
      { number: 23, text: "Sorge für dein Kleinvieh, / achte auf deine Herden," },
      { number: 24, text: "denn Geldbesitz ist nicht von Dauer; / selbst eine Krone wird nicht immer vererbt." },
      { number: 25, text: "Ist das Heu gemacht, erscheint das frische Gras, / und man sammelt die Kräuter der Berge." },
      { number: 26, text: "Die Lämmer geben dir Kleidung / und die Böcke Geld für ein Feld." },
      { number: 27, text: "Die Ziegen geben reichlich Milch, / und du hast Nahrung für dein Haus – und noch für deine Mägde den Lebensunterhalt." },
    ] },
    { number: 28, verses: [
      { number: 1, text: "Der Schuldige flieht, auch wenn ihn keiner verfolgt; / der Gerechte tritt sicher auf wie ein Löwe." },
      { number: 2, text: "Ist Aufruhr im Land, vermehren sich die Herrscher; / durch einen klugen und einsichtigen Mann hat das Recht lange Bestand." },
      { number: 3, text: "Ein Armer, der seinesgleichen unterdrückt, / ist wie ein Wolkenbruch, der die Ernte wegschwemmt." },
      { number: 4, text: "Wer das Gesetz verlässt, wird den Gottlosen loben, / wer die Lehre beachtet, bekämpft ihn." },
      { number: 5, text: "Böse Menschen verstehen die Wahrheit nicht; / wer nach Jahwe sucht, versteht alles." },
      { number: 6, text: "Besser arm und ehrlich sein, / als ein Reicher, der krumme Wege geht." },
      { number: 7, text: "Der verständige Sohn befolgt das Gesetz, / doch wer mit Verschwendern Umgang hat, macht seinem Vater Schande." },
      { number: 8, text: "Wer seinen Besitz durch Zins und Wucher mehrt, / sammelt es für einen, der sich über Arme erbarmt." },
      { number: 9, text: "Wer auf Gottes Weisung nicht mehr hört – selbst dessen Gebet ist abscheulich." },
      { number: 10, text: "Wer ehrliche Menschen auf böse Wege führt, fällt in die eigene Grube; / doch Aufrechte nehmen Gutes in Besitz." },
      { number: 11, text: "Der Reiche hält sich selbst für klug, / doch ein verständiger Armer durchschaut ihn." },
      { number: 12, text: "Wenn Gerechte triumphieren, ist die Herrlichkeit groß; / sind Verbrecher obenauf, versteckt sich der Mensch." },
      { number: 13, text: "Wer seine Sünden verheimlicht, dem geht es nicht gut. / Doch wer sie bekennt und sie lässt, über den erbarmt sich Gott." },
      { number: 14, text: "Wohl dem, der Gott fürchtet und ehrt! / Ins Unglück stürzt, wer sich ihm verschließt." },
      { number: 15, text: "Wie ein brüllender Löwe und ein gieriger Bär, / so ist ein gottloser Herrscher für ein armes Volk." },
      { number: 16, text: "Mancher Fürst ist arm an Verstand, aber reich an Erpressung. / Wer Ausbeutung hasst, bleibt lange im Amt." },
      { number: 17, text: "Wer einen Mord auf dem Gewissen hat, / flieht oft bis in den Abgrund. / Man halte ihn nicht auf." },
      { number: 18, text: "Wer ehrlich lebt, wird Hilfe finden; / wer krumme Wege geht, / kommt plötzlich zu Fall." },
      { number: 19, text: "Wer seinen Acker bebaut, hat reichlich Brot; / wer windige Geschäfte macht, hat reichlich Not." },
      { number: 20, text: "Ein treuer Mann wird reich gesegnet; / doch wer schnell reich werden will, bleibt nicht ohne Schuld." },
      { number: 21, text: "Parteilichkeit ist gar nicht gut. / Mancher wird zum Verbrecher schon für ein Stück Brot." },
      { number: 22, text: "Nach Reichtum hastet der habgierige Mann; / er weiß nicht, dass Mangel über ihn kommt." },
      { number: 23, text: "Wer einen Menschen zurechtweist, erntet mehr Dank / als einer, der immer nur schmeichelt." },
      { number: 24, text: "Wer Vater oder Mutter beraubt und meint, das sei kein Unrecht, / der macht sich zum Freund des Verbrechers." },
      { number: 25, text: "Wer immer mehr will, erregt nur Streit; / wer auf Jahwe vertraut, hat mehr als genug." },
      { number: 26, text: "Wer auf sich selbst vertraut, ist dumm; / wer der Weisheit folgt, lebt in Sicherheit." },
      { number: 27, text: "Wer dem Armen hilft, hat keinen Mangel, / doch wer die Augen vor ihnen verschließt, / dem mangelt es nicht an Flüchen." },
      { number: 28, text: "Sind die Gottlosen obenauf, versteckt sich der Mensch; / doch wenn sie verschwinden, bekommen Gerechte die Macht." },
    ] },
    { number: 29, verses: [
      { number: 1, text: "Wer eigensinnig Ermahnungen trotzt, / wird plötzlich rettungslos zerschmettert." },
      { number: 2, text: "Wenn die Gerechten zahlreich sind, freut sich das Volk; / wenn ein Gesetzloser herrscht, seufzt es." },
      { number: 3, text: "Wer Weisheit liebt, erfreut seinen Vater; / wer sich mit Huren einlässt, bringt sein Vermögen durch." },
      { number: 4, text: "Ein König, der für Recht sorgt, gibt seinem Land Bestand; / wer nur Steuern erpresst, zerstört es." },
      { number: 5, text: "Wer seinem Mitmenschen schmeichelt, / legt ein Netz vor seinen Füßen aus." },
      { number: 6, text: "Der Böse verfängt sich im Unrecht, / doch der Gerechte singt vor Freude." },
      { number: 7, text: "Der Gerechte weiß um die Sache der Armen, / der Gottlose ist rücksichtslos." },
      { number: 8, text: "Spötter versetzen die Stadt in Erregung, / Weise beschwichtigen den Zorn." },
      { number: 9, text: "Ist ein Weiser mit einem Narren vor Gericht, / dann tobt dieser und lacht und gibt keine Ruh." },
      { number: 10, text: "Blutmenschen hassen den, der ehrlich ist, / doch die Aufrichtigen retten sein Leben." },
      { number: 11, text: "Ein Trottel lässt jeden Ärger heraus, / ein Weiser hält ihn zurück." },
      { number: 12, text: "Ein Herrscher, der auf Lügen hört, / hat nur gottlose Diener." },
      { number: 13, text: "Der Arme und der Wucherer begegnen sich, / beiden gab Jahwe das Augenlicht." },
      { number: 14, text: "Wenn ein König auch den Schwachen Recht verschafft, / hat sein Thron für immer Bestand." },
      { number: 15, text: "Stock und Ermahnung fördern Vernunft, / doch ein sich selbst überlassenes Kind macht seiner Mutter Schande." },
      { number: 16, text: "Wenn die Gottlosen sich mehren, vermehrt sich das Unrecht; / doch wer auf Gott vertraut, wird sehen, wie solche Leute untergehen." },
      { number: 17, text: "Erziehe deinen Sohn streng, dann wird er dir Ruhe bringen / und dir viel Freude bereiten." },
      { number: 18, text: "Ohne Offenbarung verwildert ein Volk, / doch wohl ihm, wenn es das Gesetz bewahrt." },
      { number: 19, text: "Mit bloßen Worten erzieht man keinen Sklaven, / er versteht sie zwar, hält sich aber nicht daran." },
      { number: 20, text: "Siehst du einen, der unüberlegt redet? / Für einen Dummen ist mehr Hoffnung als für ihn." },
      { number: 21, text: "Wer seinen Sklaven von Kind auf verwöhnt, / wird am Ende von ihm ausgenutzt." },
      { number: 22, text: "Ein zorniger Mann fängt überall Streit an, / und ein Hitzkopf ist reich an Vergehen." },
      { number: 23, text: "Überheblichkeit erniedrigt einen Menschen; / Ehre erlangt, wer nicht hoch von sich denkt." },
      { number: 24, text: "Wer mit einem Dieb die Beute teilt, muss lebensmüde sein! / Er hört den Bannfluch* des Richters, zeigt aber nicht an, was er weiß.", footnotes: ["Bannfluch. Siehe 3. Mose 5,1."] },
      { number: 25, text: "Menschenfurcht ist eine Falle, / doch wer Jahwe vertraut, ist geborgen." },
      { number: 26, text: "Viele suchen die Gunst eines Herrschers, / doch nur Jahwe verschafft ihnen Recht." },
      { number: 27, text: "Für den Gerechten ist der Falsche abscheulich, / und für den Schuldigen der, der geradlinig lebt." },
    ] },
    { number: 30, verses: [
      { number: 1, text: "Die folgenden Sprüche stammen von Agur Ben-Jake aus Massa*.Das Wort des Mannes an Itiël*:\"Ohnmächtig bin ich, Gott, / ohnmächtig! Was könnte ich denn?", heading: "30-31: Gegründet in Weisheit\nDie Sprüche Agurs", footnotes: ["Wenn Massa hier und in Sprüche 31,1 geografisch gemeint ist, haben wir es bei Agur und Lemuel mit Ismaëliten zu tun (siehe 1. Mose 25,13-14), wahrscheinlich gottesfürchtigen Nicht-Israeliten wie zum Beispiel Hiob. Manche deuten den Begriff hier aber als \"Prophetenwort\", wörtlich: \"Last(-Wort)\".", "Itiël, Hebräisch: mit mir ist Gott. Der folgende Satz ist sehr schwer zu deuten."] },
      { number: 2, text: "Ich bin zu dumm für einen Mann, / mir fehlt der Menschenverstand." },
      { number: 3, text: "Ich habe keine Weisheit gelernt / und weiß nichts von dem heiligen Gott.\"" },
      { number: 4, text: "Wer stieg je in den Himmel hinauf und kam wieder herab? / Wer hat den Wind in seine Fäuste gepackt? / Wer band die Wasser in ein Tuch? / Wer hat die Grenzen der Erde bestimmt? / Wie heißt dieser Mann und wer ist sein Sohn? / Sag es mir, wenn du es weißt!" },
      { number: 5, text: "Was Gott sagt, ist die reine Wahrheit. / Wer Zuflucht sucht, hat in ihm einen Schild." },
      { number: 6, text: "Füg seinen Worten nichts Eigenes hinzu, / sonst weist er dich zurecht, und du stehst als Lügner da." },
      { number: 7, text: "Um zweierlei bitte ich dich; schenke es mir, / solange ich am Leben bin:" },
      { number: 8, text: "Falschheit und Lügenwort halte mir fern! / Armut und Reichtum gib mir bitte nicht! / Lass mich das Brot, das ich brauche, genießen," },
      { number: 9, text: "damit ich nicht satt dich verleugne und sage: \"Wer ist denn Jahwe?\" / und auch nicht verarmt anfange zu stehlen und mich vergreife am Namen Jahwes." },
      { number: 10, text: "Verleumde den Sklaven nicht bei seinem Herrn, / sonst verflucht er dich und du musst es büßen." },
      { number: 11, text: "Was ist das für eine Generation, die den Vater verflucht, / und der Mutter kein gutes Wort gibt;" },
      { number: 12, text: "die rein ist in den eigenen Augen, / doch besudelt mit persönlicher Schuld;" },
      { number: 13, text: "die hoch von sich denkt / und verachtungsvoll blickt;" },
      { number: 14, text: "deren Zähne Schwerter sind / und deren Gebiss scharfe Messer; / die die Hilflosen im Land verschlingt / und die Armen unter den Menschen!" },
      { number: 15, text: "Der Blutegel hat zwei Töchter: \"Gib her, gib her!\" / Drei werden niemals satt, und vier sagen nie: \"Es ist genug\" –", heading: "Zahlensprüche" },
      { number: 16, text: "die Totenwelt und der unfruchtbare Mutterschoß; / die Erde, die nicht genug Wasser bekommt; / und das Feuer, das niemals sagt: \"Genug!\"" },
      { number: 17, text: "Ein Auge, das den Vater verspottet / und der Mutter nicht gehorchen will – die Raben am Bach hacken es aus, / und die jungen Geier fressen es auf." },
      { number: 18, text: "Drei Dinge sind mir zu wunderbar, / vier vermag ich nicht zu erfassen:" },
      { number: 19, text: "der Weg des Adlers am Himmel, / der Weg einer Schlange auf dem Fels, / der Weg des Schiffes auf hoher See, / der Weg eines Mannes zu einer Frau." },
      { number: 20, text: "Dies ist der Weg einer Ehebrecherin: / Sie genießt, wischt sich den Mund und sagt: / \"Ich hab doch nichts Böses getan!\"" },
      { number: 21, text: "Unter drei Dingen zittert ein Land, / und vier kann es nicht ertragen:" },
      { number: 22, text: "wenn ein Sklave König wird / und wenn ein Narr zu Wohlstand kommt;" },
      { number: 23, text: "wenn eine Verschmähte geheiratet wird / und wenn eine Sklavin ihre Herrin beerbt." },
      { number: 24, text: "Die vier sind zwar die kleinsten im Land, / doch weiser als die Weisen:" },
      { number: 25, text: "Die Ameisen sind kein mächtiges Volk, / doch sammeln sie ihren Vorrat im Sommer;" },
      { number: 26, text: "die Klippdachse sind nicht stark, / doch sie bauen ihre Wohnung im Fels;" },
      { number: 27, text: "Heuschrecken haben keinen König, / und doch schwärmen sie geordnet aus;" },
      { number: 28, text: "Eidechsen fängt man mit der Hand, / und doch sind sie sogar im Königspalast." },
      { number: 29, text: "Drei haben einen stattlichen Gang / und vier schreiten stolz daher:" },
      { number: 30, text: "Der Löwe, der Held unter den Tieren, / der vor niemand zurückweicht;" },
      { number: 31, text: "der stolzierende Hahn, der Ziegenbock / und der König, wenn die Krieger bei ihm sind." },
      { number: 32, text: "Und wenn du dich stolz erhoben hast und hast dich blamiert, / oder hast du es auch nur gedacht, dann leg dir die Hand auf den Mund;" },
      { number: 33, text: "denn das Stampfen der Milch bringt Butter hervor, / das Stoßen der Nase Blut / und das Anstoßen des Zornes Streit." },
    ] },
    { number: 31, verses: [
      { number: 1, text: "Die folgenden Sprüche stammen von König Lemuel aus Massa. Es sind Ratschläge, die er von seiner Mutter erhielt:", heading: "Mahnungen für den König" },
      { number: 2, text: "Was soll ich dir sagen, mein Sohn, / du Sohn meines Leibes, den ich von Gott erbat?" },
      { number: 3, text: "Gib nicht den Frauen deine Kraft, / geh nicht die Wege, die Könige verderben." },
      { number: 4, text: "Wein ist nichts für Könige, Lemuel, / Könige dürfen sich nicht betrinken! / Auch Bier ist nichts für einen Herrscher!" },
      { number: 5, text: "Sonst betrinkt er sich, / vergisst seine Pflicht / und verdreht dem Armen das Recht." },
      { number: 6, text: "Gib das Bier dem, der zugrunde geht, / den Wein den Verbitterten." },
      { number: 7, text: "Solch einer trinkt und vergisst seine Armut, / und an die Mühsal denkt er nicht mehr.*", footnotes: ["... denkt er nicht mehr. Hier ist nicht gesagt, dass es für einen Armen gut wäre, sich zu betrinken, sondern dass es bei ihm weniger Schaden anrichtet, als bei einem König, weil dieser dadurch verantwortungslos handelt, seine Pflicht vergisst und dem Armen das Recht verdreht."] },
      { number: 8, text: "Sprich du für die Sprachlosen! / Tritt du für die Schwachen und ihren Rechtsanspruch ein!" },
      { number: 9, text: "Richte gerecht und verschaffe dem Recht, / der sich nicht helfen kann!" },
      { number: 10, text: "* Das kostbarste Juwel, das einer finden kann, / ist eine tüchtige Frau.", heading: "Lob einer tatkräftigen Frau", footnotes: ["Der folgende Text ist ein alphabetisches Gedicht. Jeder Vers beginnt mit dem jeweils nächsten Buchstaben des hebräischen Alphabets."] },
      { number: 11, text: "Ihr Mann verlässt sich auf sie, / und ihm fehlt es nie an Gewinn." },
      { number: 12, text: "Sie tut ihm Liebes und kein Leid / ihr ganzes Leben lang." },
      { number: 13, text: "Sie sorgt für Wolle und Flachs / und verarbeitet es mit fleißiger Hand." },
      { number: 14, text: "Sie gleicht den Handelsschiffen, / denn von weit her holt sie Nahrung herbei." },
      { number: 15, text: "Vor Tagesanbruch steht sie auf, / bereitet die Mahlzeiten vor / und gibt auch den Mägden ihr Teil." },
      { number: 16, text: "Sie überlegt es und kauft ein Stück Feld, / vom Ertrag ihrer Arbeit bepflanzt sie den Weinberg." },
      { number: 17, text: "Sie packt ihre Arbeit energisch an, / ist voller Tatkraft am Werk." },
      { number: 18, text: "Sie merkt, dass ihr Fleiß etwas bringt, / und arbeitet bei Licht bis spät in die Nacht." },
      { number: 19, text: "Nach der Spinnrolle greift ihre Hand, / ihre Finger fassen die Spindel." },
      { number: 20, text: "Für Notleidende hat sie eine offene Hand, / und den Armen gibt sie gern." },
      { number: 21, text: "Sie macht sich keine Sorgen um den Schnee, / denn für alle im Haus hat sie doppelte Kleidung." },
      { number: 22, text: "Sie fertigt schöne Decken an / und kleidet sich in feines Leinen und purpurrotes Gewand." },
      { number: 23, text: "Ihr Mann wird von allen geachtet, / sein Wort zählt im Rat der Gemeinde." },
      { number: 24, text: "Sie fertigt Hemden und verkauft sie, / Gürtel liefert sie dem Händler." },
      { number: 25, text: "In Kraft und Würde ist sie gekleidet / und lacht dem nächsten Tag zu." },
      { number: 26, text: "Was sie sagt, ist gut überlegt, / freundlich gibt sie ihre Weisungen." },
      { number: 27, text: "Sie behält im Auge, was im Hause vor sich geht, / das Brot der Faulheit isst sie nicht." },
      { number: 28, text: "Ihre Söhne stehen auf und preisen ihr Glück, / ihr Ehemann lobt sie und sagt:" },
      { number: 29, text: "\"Es gibt viele tüchtige Frauen, / doch du übertriffst sie alle!\"" },
      { number: 30, text: "Anmut täuscht und Schönheit vergeht, / doch eine Frau, die Jahwe ehrt, werde gelobt!" },
      { number: 31, text: "Lasst sie den Lohn ihres Schaffens genießen, / ihre Taten sprechen für sie im Rat der Gemeinde." },
    ] },
  ],
};